1	import { z } from 'zod';
2	import { isSafeUrl, stripControlChars } from '../../utils/helpers/text.util';
3	
4	/**
5	 * Format blok mengikuti BlockNote (TASK_003 §Block format).
6	 * content_json = { props, content } — properti yang tidak dikenal dibuang (z.object default = strip).
7	 */
8	
9	const color = z.string().max(32).regex(/^[a-zA-Z0-9#_-]*$/);
10	const alignment = z.enum(['left', 'center', 'right', 'justify']);
11	const cleanText = (max: number) => z.string().max(max).transform(stripControlChars);
12	const httpUrl = z.string().max(2048).refine((v) => v === '' || isSafeUrl(v), 'URL harus http:// atau https://');
13	const linkUrl = z.string().max(2048).refine((v) => isSafeUrl(v, true), 'Link harus http(s):// atau mailto:');
14	
15	const styles = z
16	  .object({
17	    bold: z.boolean().optional(),
18	    italic: z.boolean().optional(),
19	    underline: z.boolean().optional(),
20	    strike: z.boolean().optional(),
21	    code: z.boolean().optional(),
22	    textColor: color.optional(),
23	    backgroundColor: color.optional(),
24	  })
25	  .default({});
26	
27	export const styledText = z.object({ type: z.literal('text'), text: cleanText(10_000), styles });
28	const link = z.object({ type: z.literal('link'), href: linkUrl, content: z.array(styledText).max(200) });
29	export const mentionInline = z.object({
30	  type: z.literal('mention'),
31	  props: z.object({
32	    mention_type: z.enum(['user', 'agent']),
33	    id: z.uuid().transform((v) => v.toLowerCase()),
34	    label: cleanText(100).pipe(z.string().min(1)),
35	  }),
36	});
37	const inline = z.discriminatedUnion('type', [styledText, link, mentionInline]);
38	const inlineArray = z.array(inline).max(2000).default([]);
39	const textOnlyArray = z.array(styledText).max(2000).default([]);
40	
41	const textProps = z.object({
42	  textColor: color.optional(),
43	  backgroundColor: color.optional(),
44	  textAlignment: alignment.optional(),
45	});
46	
47	const tableCellProps = z
48	  .object({
49	    backgroundColor: color.optional(),
50	    textColor: color.optional(),
51	    textAlignment: alignment.optional(),
52	    colspan: z.number().int().min(1).max(20).optional(),
53	    rowspan: z.number().int().min(1).max(50).optional(),
54	  })
55	  .default({});
56	const tableCell = z.union([inlineArray, z.object({ type: z.literal('tableCell'), props: tableCellProps, content: inlineArray })]);
57	const tableContent = z.object({
58	  type: z.literal('tableContent'),
59	  columnWidths: z.array(z.number().positive().max(4000).nullable()).max(20).optional(),
60	  headerRows: z.number().int().min(0).max(1).optional(),
61	  headerCols: z.number().int().min(0).max(1).optional(),
62	  rows: z.array(z.object({ cells: z.array(tableCell).max(20) })).max(50),
63	});
64	
65	const withContent = <P extends z.ZodType, C extends z.ZodType>(props: P, content: C) =>
66	  z.object({ props: props.default({} as never), content });
67	const propsOnly = <P extends z.ZodType>(props: P) => z.object({ props: props.default({} as never) });
68	
69	/** Schema content_json per block_type. */
70	export const BLOCK_SCHEMAS = {
71	  paragraph: withContent(textProps, inlineArray),
72	  heading: withContent(
73	    textProps.extend({ level: z.union([z.literal(1), z.literal(2), z.literal(3)]).default(1), isToggleable: z.boolean().optional() }),
74	    inlineArray,
75	  ),
76	  toggleListItem: withContent(textProps, inlineArray),
77	  bulletListItem: withContent(textProps, inlineArray),
78	  numberedListItem: withContent(textProps.extend({ start: z.number().int().min(1).max(100000).optional() }), inlineArray),
79	  checkListItem: withContent(textProps.extend({ checked: z.boolean().default(false) }), inlineArray),
80	  quote: withContent(textProps, inlineArray),
81	  codeBlock: withContent(z.object({ language: z.string().max(32).regex(/^[a-zA-Z0-9+#._-]*$/).optional() }), textOnlyArray),
82	  table: withContent(z.object({ textColor: color.optional(), backgroundColor: color.optional() }), tableContent.optional()),
83	  image: propsOnly(
84	    z.object({
85	      url: httpUrl.default(''),
86	      caption: cleanText(1000).optional(),
87	      name: cleanText(255).optional(),
88	      previewWidth: z.number().positive().max(4000).optional(),
89	      showPreview: z.boolean().optional(),
90	      textAlignment: alignment.optional(),
91	      backgroundColor: color.optional(),
92	    }),
93	  ),
94	  divider: propsOnly(z.object({})),
95	  bookmark: propsOnly(
96	    z.object({
97	      url: httpUrl.default(''), // '' = placeholder yang belum diisi user
98	      title: cleanText(300).optional(),
99	      description: cleanText(1000).optional(),
100	    }),
101	  ),
102	  aiPrompt: propsOnly(
103	    z.object({
104	      prompt: cleanText(4000).default(''),
105	      agent_id: z.union([z.uuid(), z.literal('')]).nullable().optional(),
106	      status: z.enum(['idle', 'running', 'completed', 'failed']).default('idle'),
107	      last_run_id: z.union([z.uuid(), z.literal('')]).nullable().optional(),
108	    }),
109	  ),
110	} as const;
111	
112	export type BlockType = keyof typeof BLOCK_SCHEMAS;
113	export const BLOCK_TYPES = Object.keys(BLOCK_SCHEMAS) as BlockType[];
114	
115	export interface InlineText {
116	  type: 'text';
117	  text: string;
118	  styles?: Record<string, unknown>;
119	}
120	export interface InlineLink {
121	  type: 'link';
122	  href: string;
123	  content: InlineText[];
124	}
125	export interface InlineMention {
126	  type: 'mention';
127	  props: { mention_type: 'user' | 'agent'; id: string; label: string };
128	}
129	export type Inline = InlineText | InlineLink | InlineMention;
130	
131	export interface BlockContent {
132	  props: Record<string, unknown>;
133	  content?: unknown;
134	}
135	
136	export type BlockValidationResult = { ok: true; content: BlockContent } | { ok: false; issues: { path: string; message: string }[] };
137	
138	export function isBlockType(value: string): value is BlockType {
139	  return Object.prototype.hasOwnProperty.call(BLOCK_SCHEMAS, value);
140	}
141	
142	/** Validasi & bersihkan content_json untuk block_type tertentu. */
143	export function validateBlockContent(blockType: string, contentJson: unknown): BlockValidationResult {
144	  if (!isBlockType(blockType)) {
145	    return { ok: false, issues: [{ path: 'block_type', message: `block_type tidak dikenal: ${blockType}` }] };
146	  }
147	  const result = BLOCK_SCHEMAS[blockType].safeParse(contentJson ?? {});
148	  if (!result.success) {
149	    return { ok: false, issues: result.error.issues.map((i) => ({ path: `content_json.${i.path.join('.')}`, message: i.message })) };
150	  }
151	  return { ok: true, content: result.data as BlockContent };
152	}
153	
154	function inlineToText(items: unknown): string {
155	  if (!Array.isArray(items)) return '';
156	  return (items as Inline[])
157	    .map((i) => {
158	      if (i.type === 'text') return i.text;
159	      if (i.type === 'link') return i.content.map((c) => c.text).join('');
160	      if (i.type === 'mention') return `@${i.props.label}`;
161	      return '';
162	    })
163	    .join('');
164	}
165	
166	function tableRows(content: unknown): unknown[][] {
167	  const rows = (content as { rows?: { cells: unknown[] }[] } | undefined)?.rows ?? [];
168	  return rows.map((r) => r.cells.map((c) => (Array.isArray(c) ? c : (c as { content: unknown }).content)));
169	}
170	
171	/** Teks polos untuk full-text search & task_description agent. */
172	export function extractPlainText(blockType: string, content: BlockContent): string {
173	  const p = content.props ?? {};
174	  switch (blockType) {
175	    case 'table':
176	      return tableRows(content.content)
177	        .map((cells) => cells.map(inlineToText).join(' | '))
178	        .join('\n');
179	    case 'image':
180	      return [p.caption, p.name].filter(Boolean).join(' ');
181	    case 'bookmark':
182	      return [p.title, p.description, p.url].filter(Boolean).join(' ');
183	    case 'aiPrompt':
184	      return String(p.prompt ?? '');
185	    case 'divider':
186	      return '';
187	    default:
188	      return inlineToText(content.content);
189	  }
190	}
191	
192	function collectInline(content: BlockContent): unknown[] {
193	  if (Array.isArray(content.content)) return content.content;
194	  return tableRows(content.content).flat(2);
195	}
196	
197	/** Daftar mention di dalam blok. */
198	export function extractMentions(content: BlockContent): { mention_type: 'user' | 'agent'; id: string }[] {
199	  return (collectInline(content) as Inline[])
200	    .filter((i): i is InlineMention => i?.type === 'mention')
201	    .map((m) => ({ mention_type: m.props.mention_type, id: m.props.id }));
202	}
203	
204	/** Ganti mention yang tidak valid (bukan member/agent workspace) menjadi teks biasa "@label". */
205	export function replaceInvalidMentions(content: BlockContent, isValid: (m: InlineMention['props']) => boolean): BlockContent {
206	  const fix = (items: unknown): unknown =>
207	    Array.isArray(items)
208	      ? (items as Inline[]).map((i) =>
209	          i?.type === 'mention' && !isValid(i.props) ? { type: 'text', text: `@${i.props.label}`, styles: {} } : i,
210	        )
211	      : items;
212	
213	  if (Array.isArray(content.content)) return { ...content, content: fix(content.content) };
214	  const table = content.content as { type?: string; rows?: { cells: unknown[] }[] } | undefined;
215	  if (table?.type === 'tableContent' && table.rows) {
216	    return {
217	      ...content,
218	      content: {
219	        ...table,
220	        rows: table.rows.map((r) => ({
221	          cells: r.cells.map((c) => (Array.isArray(c) ? fix(c) : { ...(c as object), content: fix((c as { content: unknown }).content) })),
222	        })),
223	      },
224	    };
225	  }
226	  return content;
227	}
