146	      if (out.end_date < out.start_date || out.start_date < today) throw new Error('Estimasi tanggal tidak valid');
147	
148	      await this.prisma.tx(async (tx) => {
149	        // Hanya isi jika tanggal masih kosong (tanggal dari user tidak ditimpa)
