224	      where: { OR: [{ id: rootId }, { parent_comment_id: rootId }], deleted_at: null },
225	      include: { author_user: { select: { display_name: true } }, author_agent: { select: { name: true } } },
226	      orderBy: { created_at: 'asc' },
227	      take: 50,
228	    });
229	    const blocks = await this.payloads.contextBlocks(run.project_id, run.task_id);
230	
231	    if (!(await this.stillQueued(run.id))) return;
232	    const out = dispatchOutputSchema.parse(
233	      await this.mcp.callTool(
234	        'pm_notify_agent_mention',
235	        {
236	          contract_version: MCP_CONTRACT_VERSION,
237	          run_id: run.id,
238	          agent_key: run.agent.mcp_agent_key,
