241	          project_id: run.project_id,
242	          comment: {
243	            id: comment.id,
244	            parent_comment_id: comment.parent_comment_id,
245	            content: comment.content,
246	            author: { type: comment.author_type, id: comment.author_user_id, display_name: comment.author_user?.display_name ?? null },
247	            created_at: comment.created_at.toISOString(),
248	          },
249	          thread: thread.map((c) => ({
250	            id: c.id,
251	            content: c.content,
252	            author: {
253	              type: c.author_type,
254	              id: c.author_user_id ?? c.author_agent_id,
255	              display_name: c.author_user?.display_name ?? c.author_agent?.name ?? 'Sistem',
256	            },
257	          })),
258	          context_blocks: blocks,
259	          callback: this.payloads.callback(),
260	        },
261	        this.config.env.MCP_CALL_TIMEOUT_MS,
262	      ),
263	    );
