270	    if (!block) throw new UnrecoverableError('BLOCK_DELETED: Prompt block tidak ditemukan');
271	    const props = ((block.content_json ?? {}) as { props?: { prompt?: string } }).props ?? {};
272	    const blocks = await this.payloads.contextBlocks(run.project_id, run.task_id);
273	
274	    if (!(await this.stillQueued(run.id))) return;
275	    const out = dispatchOutputSchema.parse(
276	      await this.mcp.callTool(
277	        'pm_execute_prompt_block',
278	        {
279	          contract_version: MCP_CONTRACT_VERSION,
280	          run_id: run.id,
281	          agent_key: run.agent.mcp_agent_key,
282	          agent_id: run.agent_id,
283	          task: run.task ? this.payloads.taskSnapshot(run.task, run.workspace_id) : null,
284	          project_id: run.project_id,
285	          prompt_block: { id: block.id, prompt: props.prompt ?? '', version: block.version },
286	          context_blocks: blocks,
287	          callback: this.payloads.callback(),
288	        },
289	        this.config.env.MCP_CALL_TIMEOUT_MS,
290	      ),
291	    );
292	    await this.markDispatched(run, out);
293	  }
294	
295	  // ---------- cancel ----------
296	  private async cancel(data: McpJobData): Promise<void> {
297	    cancelOutputSchema.parse(
298	      await this.mcp.callTool(
299	        'pm_cancel_agent_run',
300	        { contract_version: MCP_CONTRACT_VERSION, run_id: data.run_id, mcp_run_id: data.mcp_run_id ?? null, reason: data.reason ?? 'user_cancelled' },
301	        this.config.env.MCP_CALL_TIMEOUT_MS,
302	      ),
303	    );
304	  }
305	
306	  // ---------- helpers ----------
307	  private async stillQueued(runId: string): Promise<boolean> {
308	    const r = await this.prisma.agent_runs.findUnique({ where: { id: runId }, select: { status: true } });
309	    return r?.status === 'queued';
310	  }
311	
312	  private async markDispatched(run: agent_runs, out: { accepted: boolean; mcp_run_id?: string }): Promise<void> {
313	    if (!out.accepted) throw new UnrecoverableError('DISPATCH_REJECTED: MCP Server menolak pekerjaan');
314	    const effects = new AfterCommit();
315	    await this.prisma.tx(async (tx) => {
316	      const res = await tx.agent_runs.updateMany({
317	        where: { id: run.id, status: 'queued' },
318	        data: { status: 'dispatched', mcp_run_id: out.mcp_run_id ?? null, last_event_at: new Date() },
319	      });
320	      if (res.count === 0) return;
321	      await this.activity.log(
322	        tx,
323	        {
324	          workspaceId: run.workspace_id,
325	          projectId: run.project_id,
326	          entityType: 'task',
327	          entityId: run.task_id ?? run.project_id,
328	          action: 'agent.dispatched',
329	          actor: { type: 'system', id: null },
330	          metadata: { run_id: run.id, trigger: run.trigger, agent_id: run.agent_id, task_id: run.task_id },
331	        },
332	        effects,
333	      );
334	    });
335	    await effects.run();
336	  }
337	
338	  /** Dipanggil BullMQ saat job gagal; pada kegagalan final run ditandai failed. */
339	  private async onFailed(job: Job<McpJobData> | undefined, err: Error): Promise<void> {
340	    if (!job) return;
341	    const final = err.name === 'UnrecoverableError' || job.attemptsMade >= (job.opts.attempts ?? 1);
342	    this.logger.warn({ run_id: job.data.run_id, kind: job.data.kind, attempt: job.attemptsMade, final, err: err.message }, 'Job MCP gagal');
343	    if (!final || job.data.kind === 'cancel') return;
344	
345	    const run = await this.prisma.agent_runs.findUnique({ where: { id: job.data.run_id } });
346	    if (!run) return;
347	    const [code, ...rest] = err.message.split(': ');
348	    const hasCode = rest.length > 0 && /^[A-Z_]+$/.test(code);
349	    const effects = new AfterCommit();
350	    await this.prisma.tx((tx) =>
351	      this.runs.failRun(
352	        tx,
353	        run,
354	        { code: hasCode ? code : 'MCP_UNAVAILABLE', message: hasCode ? rest.join(': ') : err.message, retryable: false },
355	        effects,
356	      ),
357	    );
358	    await effects.run();
359	  }
360	}
