1	import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
2	import { Job, UnrecoverableError, Worker } from 'bullmq';
3	import { AppConfigService } from '../../config/app-config.service';
4	import { MCP_CONTRACT_VERSION } from '../../common/constants/domain';
5	import { Actor } from '../../common/types/request.types';
6	import { PrismaService } from '../../database/prisma.service';
7	import { agent_runs, Prisma } from '../../generated/prisma/client';
8	import { RedisService } from '../../redis/redis.service';
9	import { cancelOutputSchema, dispatchOutputSchema, estimationOutputSchema } from '../../shared/schemas/mcp.schema';
10	import { AfterCommit } from '../../utils/helpers/after-commit';
11	import { fromDateString, todayInTimezone } from '../../utils/helpers/date.util';
12	import { ActivityService } from '../activity/activity.service';
13	import { RealtimeEvent } from '../realtime/realtime.events';
14	import { RealtimeService } from '../realtime/realtime.service';
15	import { TaskReaderService } from '../tasks/task-reader.service';
16	import { AgentRunsService } from './agent-runs.service';
17	import { McpCallError, McpClientService } from './mcp-client.service';
18	import { McpPayloadBuilder } from './mcp-payload.builder';
19	import { MCP_QUEUE, McpJobData } from './mcp-queue.service';
20	
21	const runInclude = {
22	  agent: true,
23	  workspace: { select: { id: true, timezone: true } },
24	  task: true,
25	  dispatcher: { select: { id: true, display_name: true } },
26	} satisfies Prisma.agent_runsInclude;
27	type RunWithRelations = Prisma.agent_runsGetPayload<{ include: typeof runInclude }>;
28	
29	/** Worker antrian mcp-outbound: estimasi, dispatch, mention, prompt block, cancel. */
30	@Injectable()
31	export class McpOutboundWorker implements OnModuleInit, OnModuleDestroy {
32	  private readonly logger = new Logger(McpOutboundWorker.name);
33	  private worker: Worker<McpJobData> | null = null;
34	
35	  constructor(
36	    private readonly config: AppConfigService,
37	    private readonly redis: RedisService,
38	    private readonly prisma: PrismaService,
39	    private readonly mcp: McpClientService,
40	    private readonly payloads: McpPayloadBuilder,
41	    private readonly runs: AgentRunsService,
42	    private readonly activity: ActivityService,
43	    private readonly realtime: RealtimeService,
44	    private readonly taskReader: TaskReaderService,
45	  ) {}
46	
47	  onModuleInit(): void {
48	    if (!this.config.env.RUN_WORKERS) return;
49	    this.worker = new Worker<McpJobData>(MCP_QUEUE, (job) => this.process(job), {
50	      connection: this.redis.createConnection('bullmq-worker', { forBullmq: true }),
51	      concurrency: 5,
52	    });
53	    this.worker.on('failed', (job, err) => void this.onFailed(job, err));
54	    this.worker.on('error', (err) => this.logger.warn(`Worker error: ${err.message}`));
55	    this.logger.log('Worker mcp-outbound aktif');
56	  }
57	
58	  async onModuleDestroy(): Promise<void> {
59	    await this.worker?.close().catch(() => undefined);
60	  }
61	
62	  async process(job: Job<McpJobData>): Promise<void> {
63	    const { kind, run_id } = job.data;
64	    if (kind === 'cancel') return this.cancel(job.data);
65	
66	    const run = await this.prisma.agent_runs.findUnique({ where: { id: run_id }, include: runInclude });
67	    if (!run || run.status !== 'queued') {
68	      this.logger.debug({ run_id, status: run?.status }, 'Run tidak lagi queued, job dilewati');
69	      return;
70	    }
71	    if (!run.agent.is_active || run.agent.deleted_at) throw new UnrecoverableError('AGENT_INACTIVE: Agent tidak aktif');
72	    await this.prisma.agent_runs.update({ where: { id: run.id }, data: { attempts: { increment: 1 } } });
73	
74	    try {
75	      if (kind === 'dispatch') await this.dispatch(run);
76	      else if (kind === 'mention') await this.mention(run);
77	      else if (kind === 'prompt_block') await this.promptBlock(run);
78	    } catch (err) {
79	      if (err instanceof McpCallError && !err.retryable) throw new UnrecoverableError(`${err.code}: ${err.message}`);
80	      throw err;
81	    }
82	  }
83	
84	  // ---------- dispatch (assignment) ----------
85	  private async dispatch(run: RunWithRelations): Promise<void> {
86	    const task = run.task;
87	    if (!task || task.deleted_at) throw new UnrecoverableError('TASK_DELETED: Task sudah dihapus');
88	
89	    if (!task.start_date && !task.end_date) await this.estimate(run);
90	
91	    const fresh = await this.prisma.tasks.findUniqueOrThrow({ where: { id: task.id } });
92	    const blocks = await this.payloads.contextBlocks(task.project_id, task.id);
93	    const subtasks = await this.prisma.tasks.findMany({
94	      where: { parent_task_id: task.id, deleted_at: null },
95	      select: { id: true, title: true, status: true, depth: true },
96	      orderBy: { order_index: 'asc' },
97	    });
98	
99	    if (!(await this.stillQueued(run.id))) return;
100	    const out = dispatchOutputSchema.parse(
101	      await this.mcp.callTool(
102	        'pm_dispatch_task_to_agent',
103	        {
104	          contract_version: MCP_CONTRACT_VERSION,
105	          run_id: run.id,
106	          agent_key: run.agent.mcp_agent_key,
107	          agent_id: run.agent_id,
108	          task: this.payloads.taskSnapshot(fresh, run.workspace_id),
109	          task_description: this.payloads.description(blocks),
110	          context_blocks: blocks,
111	          subtasks,
112	          dispatched_by: run.dispatcher ? { user_id: run.dispatcher.id, display_name: run.dispatcher.display_name } : null,
113	          callback: this.payloads.callback(),
114	          limits: { max_depth: 3, max_subtasks_per_event: 20, max_blocks_per_event: 50 },
115	        },
116	        this.config.env.MCP_CALL_TIMEOUT_MS,
117	      ),
118	    );
119	    await this.markDispatched(run, out);
120	  }
