125	    const agentActor: Actor = { type: 'agent', id: run.agent_id, name: run.agent.name };
126	    const today = todayInTimezone(run.workspace.timezone);
127	    const effects = new AfterCommit();
128	    try {
129	      const blocks = await this.payloads.contextBlocks(task.project_id, task.id);
130	      const out = estimationOutputSchema.parse(
131	        await this.mcp.callTool(
132	          'pm_request_agent_estimation',
