185	                reply_count: 0,
186	              },
187	            }, { actor: agentActor }),
188	          );
189	        }
190	        effects.add(async () => {
191	          const dto = await this.taskReader.getDto(task.id);
192	          if (dto) this.realtime.toProjectAndTask(task.project_id, task.id, RealtimeEvent.TASK_UPDATED, { task: dto, changed_fields: ['start_date', 'end_date'] }, { actor: agentActor });
193	        });
194	      });
195	    } catch (err) {
196	      this.logger.warn({ run_id: run.id, err: (err as Error).message }, 'Estimasi agent gagal, lanjut dispatch');
197	      await this.prisma.tx((tx) =>
198	        this.activity.log(
