338	  /** Dipanggil BullMQ saat job gagal; pada kegagalan final run ditandai failed. */
339	  private async onFailed(job: Job<McpJobData> | undefined, err: Error): Promise<void> {
340	    if (!job) return;
341	    const final = err.name === 'UnrecoverableError' || job.attemptsMade >= (job.opts.attempts ?? 1);
342	    this.logger.warn({ run_id: job.data.run_id, kind: job.data.kind, attempt: job.attemptsMade, final, err: err.message }, 'Job MCP gagal');
343	    if (!final || job.data.kind === 'cancel') return;
344	
345	    const run = await this.prisma.agent_runs.findUnique({ where: { id: job.data.run_id } });
346	    if (!run) return;
347	    const [code, ...rest] = err.message.split(': ');
348	    const hasCode = rest.length > 0 && /^[A-Z_]+$/.test(code);
349	    const effects = new AfterCommit();
350	    await this.prisma.tx((tx) =>
351	      this.runs.failRun(
352	        tx,
353	        run,
354	        { code: hasCode ? code : 'MCP_UNAVAILABLE', message: hasCode ? rest.join(': ') : err.message, retryable: false },
355	        effects,
356	      ),
357	    );
358	    await effects.run();
359	  }
360	}
