1	import { Injectable, Logger } from '@nestjs/common';
2	import { Client } from '@modelcontextprotocol/sdk/client/index.js';
3	import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
4	import { AppConfigService } from '../../config/app-config.service';
5	import { toolErrorSchema } from '../../shared/schemas/mcp.schema';
6	
7	/** Error pemanggilan tool MCP; retryable menentukan apakah job di-retry. */
8	export class McpCallError extends Error {
9	  constructor(
10	    readonly code: string,
11	    message: string,
12	    readonly retryable: boolean,
13	  ) {
14	    super(message);
15	    this.name = 'McpCallError';
16	  }
17	}
18	
19	export type McpToolName =
20	  | 'pm_dispatch_task_to_agent'
21	  | 'pm_request_agent_estimation'
22	  | 'pm_notify_agent_mention'
23	  | 'pm_execute_prompt_block'
24	  | 'pm_cancel_agent_run';
25	
26	/** Klien MCP (Streamable HTTP) untuk memanggil tools di Custom MCP Server (M1_MCP_INTEGRATION §2–3). */
27	@Injectable()
28	export class McpClientService {
29	  private readonly logger = new Logger(McpClientService.name);
30	
31	  constructor(private readonly config: AppConfigService) {}
32	
33	  async callTool(name: McpToolName, args: Record<string, unknown>, timeoutMs: number): Promise<unknown> {
34	    const client = new Client({ name: 'marketing-dashboard', version: '0.1.0' });
35	    const transport = new StreamableHTTPClientTransport(new URL(this.config.env.MCP_SERVER_URL), {
36	      requestInit: { headers: { Authorization: `Bearer ${this.config.env.MCP_SERVER_API_KEY}` } },
37	    });
38	    const started = Date.now();
39	    try {
40	      await client.connect(transport, { timeout: timeoutMs });
41	      const res = await client.callTool({ name, arguments: args }, undefined, { timeout: timeoutMs });
42	      const structured = res.structuredContent ?? this.parseTextContent(res.content);
43	      if (res.isError) {
44	        const parsed = toolErrorSchema.safeParse(structured);
45	        throw new McpCallError(
46	          parsed.success ? parsed.data.code : 'TOOL_ERROR',
47	          (parsed.success ? parsed.data.message : undefined) ?? `Tool ${name} mengembalikan error`,
48	          parsed.success ? (parsed.data.retryable ?? false) : false,
49	        );
50	      }
51	      this.logger.debug({ tool: name, ms: Date.now() - started }, 'MCP tool call sukses');
52	      return structured;
53	    } catch (err) {
54	      if (err instanceof McpCallError) throw err;
55	      throw new McpCallError('MCP_UNAVAILABLE', `Gagal memanggil ${name}: ${(err as Error).message}`, true);
56	    } finally {
57	      await client.close().catch(() => undefined);
58	    }
59	  }
60	
61	  private parseTextContent(content: unknown): unknown {
62	    if (!Array.isArray(content)) return undefined;
63	    const text = content.find((c: { type?: string }) => c?.type === 'text') as { text?: string } | undefined;
64	    if (!text?.text) return undefined;
65	    try {
66	      return JSON.parse(text.text);
67	    } catch {
68	      return undefined;
69	    }
70	  }
71	}
