1	import { createHash, createHmac, randomBytes, timingSafeEqual } from 'node:crypto';
2	
3	export function sha256Hex(value: string): string {
4	  return createHash('sha256').update(value).digest('hex');
5	}
6	
7	export function randomToken(bytes = 32): string {
8	  return randomBytes(bytes).toString('base64url');
9	}
10	
11	/** Perbandingan string constant-time (aman dari timing attack). */
12	export function safeEqual(a: string, b: string): boolean {
13	  const ab = Buffer.from(a);
14	  const bb = Buffer.from(b);
15	  if (ab.length !== bb.length) return false;
16	  return timingSafeEqual(ab, bb);
17	}
18	
19	/** Signature webhook MCP: "sha256=" + HMAC_SHA256(secret, "<timestamp>.<raw_body>"). */
20	export function signMcpPayload(secret: string, timestamp: string, rawBody: string | Buffer): string {
21	  const hmac = createHmac('sha256', secret);
22	  hmac.update(`${timestamp}.`);
23	  hmac.update(rawBody);
24	  return `sha256=${hmac.digest('hex')}`;
25	}
26	
27	export interface SignatureCheckInput {
28	  secrets: string[];
29	  timestamp: string | undefined;
30	  signature: string | undefined;
31	  rawBody: Buffer | undefined;
32	  toleranceSec?: number;
33	  nowSec?: number;
34	}
35	
36	export type SignatureCheckResult = 'ok' | 'missing' | 'expired' | 'invalid';
37	
38	export function verifyMcpSignature(input: SignatureCheckInput): SignatureCheckResult {
39	  const { secrets, timestamp, signature, rawBody } = input;
40	  if (!timestamp || !signature || !rawBody) return 'missing';
41	  const ts = Number(timestamp);
42	  const now = input.nowSec ?? Math.floor(Date.now() / 1000);
43	  if (!Number.isFinite(ts) || Math.abs(now - ts) > (input.toleranceSec ?? 300)) return 'expired';
44	  return secrets.some((s) => s && safeEqual(signMcpPayload(s, timestamp, rawBody), signature)) ? 'ok' : 'invalid';
45	}
