        .map((b) => ({ block_id: b.id, task_id: null, task_title: null, block_type: b.block_type, text: b.plain_text.slice(0, 2000), rank: 0 }));
    }
    return {
      results: rows.map((r) => ({ ...r, source: r.task_id ? 'task' : 'project_brief', rank: Number(r.rank) })),
    };
  }
