            secrets["MCP_SERVER_API_KEY"],
            secrets["MCP_WEBHOOK_SECRET"],
            secrets["MCP_SERVICE_TOKEN"],
        ]
        if len(set(dashboard_secrets)) != len(dashboard_secrets):
