            name = loc[-1].upper() if loc else "SETTINGS"
            message = err["msg"].removeprefix("Value error, ")
            problems.append(f"{name}: {message}" if loc else message)
        raise ConfigError("Konfigurasi tidak valid -> " + "; ".join(problems)) from None


