    re.compile(r"\bmcpk_[A-Za-z0-9_\-]+"),
    re.compile(r"\bsk-[A-Za-z0-9_\-]{16,}"),
    re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
    re.compile(r"(?<=://)[^:/@\s]+:[^@\s]+(?=@)"),
    re.compile(r"sha256=[0-9a-f]{64}"),
]
