-- Bootstrap schema mcp (DATABASE.md §3). Jalankan SEKALI sebagai superuser pada database Dashboard
-- yang sudah termigrasi Prisma. Idempoten: aman dijalankan ulang (password role diperbarui).
--   psql -v owner_pw=... -v app_pw=... -d marketing_dashboard -f scripts/sql/bootstrap.sql
\set ON_ERROR_STOP on

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- pgvector opsional saat bootstrap: revisi 0002_kb_vector butuh ekstensi ini (TASK-19)
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'vector') THEN
    CREATE EXTENSION IF NOT EXISTS vector;
  ELSE
    RAISE NOTICE 'pgvector belum terpasang di server ini; revisi 0002_kb_vector akan dilewati';
  END IF;
END $$;

SELECT 'CREATE ROLE mcp_owner LOGIN'
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'mcp_owner') \gexec
SELECT 'CREATE ROLE mcp_app LOGIN'
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'mcp_app') \gexec
SELECT format('ALTER ROLE mcp_owner LOGIN PASSWORD %L', :'owner_pw') \gexec
SELECT format('ALTER ROLE mcp_app LOGIN PASSWORD %L', :'app_pw') \gexec

SELECT format('GRANT CONNECT ON DATABASE %I TO mcp_owner, mcp_app', current_database()) \gexec

CREATE SCHEMA IF NOT EXISTS mcp AUTHORIZATION mcp_owner;
GRANT USAGE ON SCHEMA mcp TO mcp_app;
ALTER DEFAULT PRIVILEGES FOR ROLE mcp_owner IN SCHEMA mcp
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO mcp_app;
ALTER DEFAULT PRIVILEGES FOR ROLE mcp_owner IN SCHEMA mcp
  GRANT USAGE, SELECT ON SEQUENCES TO mcp_app;

-- Akses baca ke data Dashboard (schema public), berkolom
GRANT USAGE ON SCHEMA public TO mcp_app;
GRANT SELECT (id, username, display_name, avatar_url, is_active) ON public.users TO mcp_app;
GRANT SELECT ON public.workspaces, public.workspace_members, public.agents, public.projects,
               public.tasks, public.document_blocks, public.comments, public.activity_logs,
               public.agent_runs TO mcp_app;
-- TIDAK diberikan: refresh_tokens, notifications, mcp_webhook_events, users.email, users.password_hash

ALTER ROLE mcp_app SET search_path = mcp, public;
ALTER ROLE mcp_app SET statement_timeout = '30s';
ALTER ROLE mcp_app SET idle_in_transaction_session_timeout = '60s';

