            best = (path, len(node))
        children: Any = enumerate(node)
    elif isinstance(node, dict):
        children = node.items()
    else:
        return None
    for key, value in children:
        found = _largest_list(value, (*path, key))
        if found and (best is None or found[1] > best[1]):
            best = found
    return best


