25	interface HandlerContext {
26	  tx: Tx;
27	  run: RunCtx;
28	  env: WebhookEnvelope;
29	  /** Task target event (task run atau turunannya); null untuk run level project */
30	  task: tasks | null;
31	  agent: Actor;
32	  effects: AfterCommit;
33	}
34	
35	const EVENT_STALE_MS = 60_000;
36	
37	/**
38	 * Penerima webhook MCP (TASK_003 §MCP Webhook Receiver, M1_MCP_INTEGRATION §5):
39	 * validasi → idempotency → validasi run & scope task → handler per event (1 transaksi) → efek setelah commit.
40	 */
41	@Injectable()
42	export class McpWebhookService {
43	  private readonly logger = new Logger(McpWebhookService.name);
44	
45	  constructor(
46	    private readonly prisma: PrismaService,
47	    private readonly runs: AgentRunsService,
48	    private readonly blocks: BlocksService,
49	    private readonly tasks: TasksService,
50	    private readonly comments: CommentsService,
51	    private readonly notifications: NotificationsService,
52	    private readonly activity: ActivityService,
53	    private readonly realtime: RealtimeService,
54	    private readonly reader: TaskReaderService,
55	  ) {}
56	
57	  async handle(body: unknown): Promise<{ status: 'processed' | 'duplicate'; result?: unknown }> {
58	    const envParsed = webhookEnvelopeSchema.safeParse(body);
59	    if (!envParsed.success) {
60	      throw Errors.validation('Envelope webhook tidak valid', { issues: envParsed.error.issues.map((i) => ({ path: i.path.join('.'), message: i.message })) });
61	    }
62	    const env = envParsed.data;
63	    const dataParsed = eventDataSchemas[env.event_type].safeParse(env.data);
64	    if (!dataParsed.success) {
65	      throw Errors.validation(`data untuk ${env.event_type} tidak valid`, {
66	        issues: dataParsed.error.issues.map((i) => ({ path: `data.${i.path.join('.')}`, message: i.message })),
67	      });
68	    }
69	
70	    // Idempotency berdasarkan event_id
71	    const existing = await this.prisma.mcp_webhook_events.findUnique({ where: { event_id: env.event_id } });
72	    if (existing?.status === 'processed') return { status: 'duplicate' };
73	    if (existing?.status === 'processing' && Date.now() - existing.received_at.getTime() < EVENT_STALE_MS) {
74	      throw new AppException(ErrorCode.EVENT_IN_PROGRESS, 'Event sedang diproses, coba lagi', 429, { retry_after: 5 });
75	    }
76	    try {
77	      await this.prisma.mcp_webhook_events.upsert({
78	        where: { event_id: env.event_id },
79	        create: { event_id: env.event_id, event_type: env.event_type, status: 'processing' },
80	        update: { status: 'processing', error: Prisma.DbNull, received_at: new Date() },
81	      });
82	    } catch {
83	      throw new AppException(ErrorCode.EVENT_IN_PROGRESS, 'Event sedang diproses, coba lagi', 429, { retry_after: 5 });
84	    }
85	
86	    try {
87	      const result = await this.process(env, dataParsed.data);
88	      await this.prisma.mcp_webhook_events.update({
89	        where: { event_id: env.event_id },
90	        data: { status: 'processed', processed_at: new Date(), run_id: env.run_id },
91	      });
92	      return { status: 'processed', result };
93	    } catch (err) {
94	      const error =
95	        err instanceof AppException ? { code: err.code, message: err.message } : { code: 'INTERNAL_ERROR', message: (err as Error).message };
96	      await this.prisma.mcp_webhook_events
97	        .update({ where: { event_id: env.event_id }, data: { status: 'rejected', error, processed_at: new Date() } })
98	        .catch(() => undefined);
99	      this.logger.warn({ event_id: env.event_id, event_type: env.event_type, run_id: env.run_id, error }, 'Webhook MCP ditolak');
100	      throw err;
101	    }
102	  }
103	
104	  private async process(env: WebhookEnvelope, data: unknown): Promise<unknown> {
105	    const run = await this.prisma.agent_runs.findUnique({
106	      where: { id: env.run_id },
107	      include: { agent: true, workspace: { select: { id: true, timezone: true } } },
108	    });
109	    if (!run || run.agent_id !== env.agent_id) throw Errors.notFound('Agent run tidak ditemukan');
110	    if (!ACTIVE_RUN_STATUS_LIST.includes(run.status)) {
111	      throw Errors.conflict(ErrorCode.RUN_NOT_ACTIVE, `Run berstatus ${run.status}; hentikan pengiriman event`);
112	    }
113	
114	    const task = await this.resolveTargetTask(run, env);
115	    const effects = new AfterCommit();
116	    const agent: Actor = { type: 'agent', id: run.agent_id, name: run.agent.name };
117	
118	    const result = await this.prisma.tx(async (tx) => {
119	      const ctx: HandlerContext = { tx, run, env, task, agent, effects };
120	      await this.touchRun(ctx);
121	      return this.dispatchEvent(env.event_type, ctx, data);
122	    });
123	    await effects.run();
124	    return result;
125	  }
126	
127	  private dispatchEvent(type: McpEventType, ctx: HandlerContext, data: unknown): Promise<unknown> {
128	    switch (type) {
129	      case 'agent.task.started':
130	        return this.onStarted(ctx);
131	      case 'agent.status.changed':
132	        return this.onStatusChanged(ctx, data as EventData<'agent.status.changed'>);
133	      case 'agent.block.appended':
134	        return this.onBlockAppended(ctx, data as EventData<'agent.block.appended'>);
135	      case 'agent.subtask.created':
136	        return this.onSubtaskCreated(ctx, data as EventData<'agent.subtask.created'>);
137	      case 'agent.comment.added':
138	        return this.onCommentAdded(ctx, data as EventData<'agent.comment.added'>);
139	      case 'agent.task.completed':
140	        return this.onCompleted(ctx, data as EventData<'agent.task.completed'>);
141	      case 'agent.task.failed':
142	        return this.onFailed(ctx, data as EventData<'agent.task.failed'>);
143	    }
144	  }
