146	  /** task_id envelope harus task milik run atau turunannya. */
147	  private async resolveTargetTask(run: agent_runs, env: WebhookEnvelope): Promise<tasks | null> {
148	    const targetId = env.task_id ?? run.task_id;
149	    if (!targetId) return null;
150	    if (!run.task_id) throw Errors.business(ErrorCode.BUSINESS_RULE_VIOLATION, 'Run level project tidak dapat menulis ke task');
151	    if (targetId !== run.task_id) {
152	      const scope = await TaskHierarchy.descendants(this.prisma, run.task_id);
153	      if (!scope.some((n) => n.id === targetId)) throw Errors.notFound('Task berada di luar cakupan run ini');
154	    }
155	    const task = await this.prisma.tasks.findFirst({ where: { id: targetId, deleted_at: null } });
156	    if (!task) throw Errors.notFound('Task tidak ditemukan');
157	    return task;
158	  }
