160	  private async touchRun({ tx, run }: HandlerContext): Promise<void> {
161	    const now = new Date();
162	    await tx.agent_runs.update({
163	      where: { id: run.id },
164	      data: { status: 'running', last_event_at: now, ...(run.started_at ? {} : { started_at: now }) },
165	    });
166	  }
