218	    const schedule = normalizeSchedule({
219	      start_date: input.start_date !== undefined ? input.start_date : toDateString(task.start_date),
220	      end_date: input.end_date !== undefined ? input.end_date : toDateString(task.end_date),
221	      is_milestone: input.is_milestone ?? task.is_milestone,
222	    });
223	
224	    const data: Prisma.tasksUncheckedUpdateInput = {};
225	    const changed: string[] = [];
226	    const changes: Record<string, { from: unknown; to: unknown }> = {};
227	    const track = (field: string, from: unknown, to: unknown) => {
228	      if (JSON.stringify(from) !== JSON.stringify(to)) {
229	        changed.push(field);
230	        changes[field] = { from, to };
231	      }
232	    };
233	
234	    if (input.title !== undefined) track('title', task.title, input.title);
235	    if (input.priority !== undefined) track('priority', task.priority, input.priority);
236	    if (input.tags !== undefined) track('tags', task.tags, uniqueTags(input.tags));
237	    track('is_milestone', task.is_milestone, schedule.is_milestone);
238	    track('start_date', toDateString(task.start_date), schedule.start_date);
239	    track('end_date', toDateString(task.end_date), schedule.end_date);
240	    if (input.status !== undefined) track('status', task.status, input.status);
241	
242	    for (const f of changed) {
243	      if (f === 'start_date' || f === 'end_date') data[f] = fromDateString(changes[f].to as string | null);
244	      else data[f as 'title'] = changes[f].to as never;
245	    }
246	    if (changed.includes('status')) {
247	      const status = input.status as task_status;
248	      data.completed_at = status === 'done' ? new Date() : null;
249	      const max = await this.prisma.tasks.aggregate({ where: { project_id: task.project_id, status, deleted_at: null }, _max: { order_index: true } });
250	      data.order_index = (max._max.order_index ?? -1) + 1;
251	    }
252	    if (assigneeChanged) {
253	      Object.assign(data, this.assignment.columns(nextAssignee ?? null));
254	      changed.push('assignee');
255	    }
256	
257	    if (changed.length === 0) return this.reader.getDto(taskId);
258	
259	    const effects = new AfterCommit();
260	    await this.prisma.tx(async (tx) => {
261	      const updated = await tx.tasks.update({ where: { id: taskId }, data });
262	      const base = { workspaceId: workspace.id, projectId: task.project_id, entityType: 'task' as const, entityId: taskId, actor };
263	
264	      if (changes.status) await this.activity.log(tx, { ...base, action: 'task.status_changed', metadata: changes.status }, effects);
265	      if (changes.start_date || changes.end_date || changes.is_milestone) {
266	        await this.activity.log(
267	          tx,
268	          {
269	            ...base,
270	            action: 'task.rescheduled',
271	            metadata: {
272	              from: { start_date: toDateString(task.start_date), end_date: toDateString(task.end_date) },
273	              to: { start_date: schedule.start_date, end_date: schedule.end_date },
274	              cascade: 'none',
275	              shifted_count: 0,
276	            },
277	          },
278	          effects,
279	        );
280	      }
281	      const generic = Object.fromEntries(Object.entries(changes).filter(([k]) => ['title', 'priority', 'tags', 'is_milestone'].includes(k)));
282	      if (Object.keys(generic).length) await this.activity.log(tx, { ...base, action: 'task.updated', metadata: { changes: generic } }, effects);
283	      if (assigneeChanged) await this.assignment.afterChange(tx, { workspaceId: workspace.id, actor }, task, updated, nextAssignee ?? null, effects);
284	    });
285	
286	    const dto = await this.reader.getDto(taskId);
287	    effects.add(() =>
288	      this.realtime.toProjectAndTask(task.project_id, taskId, RealtimeEvent.TASK_UPDATED, { task: dto, changed_fields: changed }, { actor, originClientId: clientId }),
289	    );
290	    await effects.run();
291	    return dto;
292	  }
293	
294	  // ================= Delete =================
295	
296	  async remove(user: AuthUser, taskId: string, clientId: string | null): Promise<void> {
297	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
298	    const actor = userActor(user);
299	    const effects = new AfterCommit();
300	    const deletedIds = await this.prisma.tx(async (tx) => {
301	      const nodes = await TaskHierarchy.descendants(tx, taskId);
302	      const ids = nodes.map((n) => n.id);
303	      const now = new Date();
304	      await this.runs.cancelActive(tx, { task_id: { in: ids } }, 'task_deleted', actor, effects);
305	      await tx.tasks.updateMany({ where: { id: { in: ids } }, data: { deleted_at: now } });
306	      const blocks = await tx.document_blocks.findMany({ where: { task_id: { in: ids }, deleted_at: null }, select: { id: true } });
307	      await tx.document_blocks.updateMany({ where: { task_id: { in: ids }, deleted_at: null }, data: { deleted_at: now } });
308	      await tx.comments.updateMany({
309	        where: { deleted_at: null, OR: [{ entity_type: 'task', entity_id: { in: ids } }, { entity_type: 'block', entity_id: { in: blocks.map((b) => b.id) } }] },
310	        data: { deleted_at: now },
311	      });
312	      await this.activity.log(
313	        tx,
314	        {
315	          workspaceId: workspace.id,
316	          projectId: task.project_id,
317	          entityType: 'task',
318	          entityId: taskId,
319	          action: 'task.deleted',
320	          actor,
321	          metadata: { title: task.title, deleted_count: ids.length },
322	        },
323	        effects,
324	      );
325	      return ids;
326	    });
327	    effects.add(() =>
328	      this.realtime.toProjectAndTask(task.project_id, taskId, RealtimeEvent.TASK_DELETED, { task_id: taskId, deleted_ids: deletedIds }, { actor, originClientId: clientId }),
329	    );
330	    await effects.run();
331	  }
332	
333	  // ================= Duplicate =================
334	
335	  /**
336	   * Salin task beserta turunan terpilih ke parent yang sama (tepat setelah aslinya).
337	   * Salinan selalu berstatus To Do. Assignee AI Agent tidak disalin agar agent tidak otomatis bekerja.
338	   * Subtask yang parent-nya tidak dipilih ditempel ke leluhur terdekat yang ikut disalin.
339	   */
340	  async duplicate(user: AuthUser, taskId: string, input: DuplicateTaskInput, clientId: string | null) {
341	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
342	    const actor = userActor(user);
343	    const effects = new AfterCommit();
344	    const rootTitle = (input.title ?? `${task.title} (salinan)`).slice(0, 500);
345	
346	    const newIds = await this.prisma.tx(async (tx) => {
347	      // 1. Turunan yang ikut disalin, diurutkan preorder (parent selalu sebelum anaknya)
348	      const tree = input.subtasks === 'none' ? [] : await TaskHierarchy.descendants(tx, taskId);
349	      const descIds = tree.map((n) => n.id).filter((id) => id !== taskId);
350	      if (input.subtasks === 'selected') {
351	        const known = new Set(descIds);
352	        if (input.subtask_ids.some((id) => !known.has(id))) throw Errors.validation('Sebagian subtask_ids bukan turunan task ini', { field: 'subtask_ids' });
353	      }
354	      const all = descIds.length ? await tx.tasks.findMany({ where: { id: { in: descIds } } }) : [];
355	      const keep = new Set(input.subtasks === 'all' ? descIds : input.subtasks === 'selected' ? input.subtask_ids : []);
356	      const byId = new Map(all.map((t) => [t.id, t]));
357	      const parentOf = (t: tasks): string => {
358	        let p = t.parent_task_id;
359	        while (p && p !== taskId && !keep.has(p)) p = byId.get(p)?.parent_task_id ?? null;
360	        return p ?? taskId;
361	      };
362	      const children = new Map<string, tasks[]>();
363	      for (const t of all) {
364	        if (!keep.has(t.id)) continue;
365	        const p = parentOf(t);
366	        children.set(p, [...(children.get(p) ?? []), t]);
367	      }
368	      const byOrder = (a: tasks, b: tasks) => a.order_index - b.order_index || a.created_at.getTime() - b.created_at.getTime();
369	      const ordered: tasks[] = [];
370	      const walk = (pid: string) => {
371	        for (const c of (children.get(pid) ?? []).sort(byOrder)) {
372	          ordered.push(c);
373	          walk(c.id);
374	        }
375	      };
376	      walk(taskId);
377	
378	      // 2. Timeline: sama / digeser agar task utama mulai di start_date / dikosongkan
379	      let delta = 0;
380	      if (input.timeline === 'shift' && input.start_date) {
381	        const anchor = toDateString(task.start_date) ?? ordered.map((t) => toDateString(t.start_date)).filter((d): d is string => !!d).sort()[0];
382	        if (anchor) delta = diffDays(anchor, input.start_date);
383	      }
384	      const move = (d: Date | null) => (d && delta ? fromDateString(addDays(toDateString(d) as string, delta)) : d);
385	      const schedule = (t: tasks) =>
386	        input.timeline === 'none'
387	          ? { start_date: null, end_date: null, is_milestone: false }
388	          : { start_date: move(t.start_date), end_date: move(t.end_date), is_milestone: t.is_milestone };
389	
390	      // 3. Assignee: hanya user yang masih anggota aktif non-viewer
391	      const eligible = new Set<string>();
392	      if (input.copy_assignee) {
393	        const userIds = [...new Set([task, ...ordered].map((t) => t.assignee_user_id).filter((id): id is string => !!id))];
394	        if (userIds.length) {
395	          const members = await tx.workspace_members.findMany({
396	            where: { workspace_id: workspace.id, user_id: { in: userIds }, role: { not: 'viewer' }, user: { is_active: true } },
397	            select: { user_id: true },
398	          });
399	          for (const m of members) eligible.add(m.user_id);
400	        }
401	      }
402	      const assignee = (t: tasks) =>
403	        t.assignee_type === 'user' && t.assignee_user_id && eligible.has(t.assignee_user_id)
404	          ? { assignee_type: 'user' as const, assignee_user_id: t.assignee_user_id, assignee_agent_id: null }
405	          : { assignee_type: null, assignee_user_id: null, assignee_agent_id: null };
406	      const fields = (t: tasks) => ({
407	        project_id: task.project_id,
408	        status: 'todo' as const,
409	        priority: t.priority,
410	        tags: t.tags,
411	        created_by_type: actor.type,
412	        created_by_id: actor.id,
413	        ...schedule(t),
414	        ...assignee(t),
415	      });
416	
417	      // 4. Simpan: task utama tepat setelah aslinya, turunan di akhir kolom To Do
418	      const idMap = new Map<string, string>([[taskId, randomUUID()]]);
419	      const depthOf = new Map<string, number>([[taskId, task.depth]]);
420	      const rootId = idMap.get(taskId) as string;
421	      const rootOrder = await this.nextOrderIndex(tx, task.project_id, 'todo', taskId);
422	      await tx.tasks.create({
423	        data: { ...fields(task), id: rootId, parent_task_id: task.parent_task_id, depth: task.depth, title: rootTitle, order_index: rootOrder },
424	      });
425	      if (ordered.length) {
426	        const max = await tx.tasks.aggregate({ where: { project_id: task.project_id, status: 'todo', deleted_at: null }, _max: { order_index: true } });
427	        let next = (max._max.order_index ?? -1) + 1;
428	        const rows: Prisma.tasksCreateManyInput[] = ordered.map((t) => {
429	          const parent = parentOf(t);
430	          const depth = (depthOf.get(parent) as number) + 1;
431	          const id = randomUUID();
432	          idMap.set(t.id, id);
433	          depthOf.set(t.id, depth);
434	          return { ...fields(t), id, parent_task_id: idMap.get(parent) as string, depth, title: t.title, order_index: next++ };
435	        });
436	        await tx.tasks.createMany({ data: rows });
437	      }
438	
439	      // 5. Isi dokumen task (block editor), parent blok selalu disimpan lebih dulu
440	      if (input.copy_content) {
441	        const blocks = await tx.document_blocks.findMany({ where: { task_id: { in: [...idMap.keys()] }, deleted_at: null } });
442	        const blockIds = new Map(blocks.map((b) => [b.id, randomUUID()]));
443	        const sorted: typeof blocks = [];
444	        const placed = new Set<string>();
445	        let pending = blocks;
446	        while (pending.length) {
447	          const ready = pending.filter((b) => !b.parent_block_id || !blockIds.has(b.parent_block_id) || placed.has(b.parent_block_id));
448	          if (!ready.length) break;
449	          for (const b of ready) {
450	            sorted.push(b);
451	            placed.add(b.id);
452	          }
453	          pending = pending.filter((b) => !placed.has(b.id));
454	        }
455	        if (sorted.length) {
456	          await tx.document_blocks.createMany({
457	            data: sorted.map((b) => ({
458	              id: blockIds.get(b.id) as string,
459	              project_id: task.project_id,
460	              task_id: idMap.get(b.task_id as string) as string,
461	              parent_block_id: b.parent_block_id ? (blockIds.get(b.parent_block_id) ?? null) : null,
462	              block_type: b.block_type,
463	              content_json: b.content_json as Prisma.InputJsonValue,
464	              plain_text: b.plain_text,
465	              order_index: b.order_index,
466	              last_edited_by_type: actor.type,
467	              last_edited_by_id: actor.id,
468	            })),
469	          });
470	        }
471	      }
472	
473	      await this.activity.log(
474	        tx,
475	        {
476	          workspaceId: workspace.id,
477	          projectId: task.project_id,
478	          entityType: 'task',
479	          entityId: rootId,
480	          action: 'task.duplicated',
481	          actor,
482	          metadata: { title: rootTitle, source_task_id: taskId, source_title: task.title, subtask_count: ordered.length, parent_task_id: task.parent_task_id },
483	        },
484	        effects,
485	      );
486	      return [...idMap.values()];
487	    });
488	
489	    const dtos = await this.reader.getDtos(newIds);
490	    effects.add(() => {
491	      for (const dto of dtos) this.realtime.toProject(task.project_id, RealtimeEvent.TASK_CREATED, { task: dto }, { actor, originClientId: clientId });
492	    });
493	    await effects.run();
494	    return { task: dtos.find((d) => d.id === newIds[0]) ?? null, created_count: newIds.length };
495	  }
496	
497	  // ================= Move & reorder =================
498	
499	  async move(user: AuthUser, taskId: string, parentTaskId: string | null, clientId: string | null) {
500	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
501	    const actor = userActor(user);
502	    if (parentTaskId === task.parent_task_id) return this.reader.getDto(taskId);
503	
504	    const effects = new AfterCommit();
505	    const movedIds = await this.prisma.tx(async (tx) => {
506	      const subtree = await TaskHierarchy.descendants(tx, taskId);
507	      let newDepth = 1;
508	      if (parentTaskId) {
509	        if (subtree.some((n) => n.id === parentTaskId)) {
510	          throw Errors.business(ErrorCode.CIRCULAR_HIERARCHY, 'Task tidak dapat dipindahkan ke dalam turunannya sendiri');
511	        }
512	        const parent = await tx.tasks.findFirst({ where: { id: parentTaskId, deleted_at: null } });
513	        if (!parent) throw Errors.validation('parent_task_id tidak ditemukan', { field: 'parent_task_id' });
514	        if (parent.project_id !== task.project_id) {
515	          throw Errors.business(ErrorCode.CROSS_PROJECT_PARENT, 'Parent task harus berada di project yang sama');
516	        }
517	        newDepth = parent.depth + 1;
518	      }
519	      assertMoveDepth(newDepth, subtreeHeight(subtree, task.depth));
520	      const delta = newDepth - task.depth;
521	
522	      await tx.tasks.update({ where: { id: taskId }, data: { parent_task_id: parentTaskId } });
523	      if (delta !== 0) {
524	        await tx.tasks.updateMany({ where: { id: { in: subtree.map((n) => n.id) } }, data: { depth: { increment: delta } } });
525	      }
526	      await this.activity.log(
527	        tx,
528	        {
529	          workspaceId: workspace.id,
530	          projectId: task.project_id,
531	          entityType: 'task',
532	          entityId: taskId,
533	          action: 'task.moved',
534	          actor,
535	          metadata: { from_parent_id: task.parent_task_id, to_parent_id: parentTaskId },
536	        },
537	        effects,
538	      );
539	      return subtree.map((n) => n.id);
540	    });
541	    const dtos = await this.reader.getDtos(movedIds);
542	    effects.add(() => {
543	      for (const dto of dtos) {
544	        this.realtime.toProjectAndTask(task.project_id, dto.id, RealtimeEvent.TASK_UPDATED, { task: dto, changed_fields: ['parent_task_id', 'depth'] }, { actor, originClientId: clientId });
545	      }
546	    });
547	    await effects.run();
548	    return dtos.find((d) => d.id === taskId) ?? null;
549	  }
550	
551	  async reorder(user: AuthUser, projectId: string, status: task_status, orderedIds: string[], clientId: string | null) {
552	    await this.access.assertProject(user.id, projectId, 'member');
553	    const ids = [...new Set(orderedIds)];
554	    const found = await this.prisma.tasks.findMany({ where: { id: { in: ids }, project_id: projectId, deleted_at: null }, select: { id: true, status: true } });
555	    if (found.length !== ids.length) throw Errors.validation('Sebagian task tidak ditemukan di project ini', { field: 'ordered_task_ids' });
556	    if (found.some((t) => t.status !== status)) throw Errors.validation('Semua task harus berstatus sama dengan kolom', { field: 'status' });
557	
558	    const values = Prisma.join(ids.map((id, i) => Prisma.sql`(${id}::uuid, ${i}::int)`));
559	    await this.prisma.$executeRaw`
560	      UPDATE tasks AS t SET order_index = v.idx, updated_at = now()
561	      FROM (VALUES ${values}) AS v(id, idx)
562	      WHERE t.id = v.id AND t.project_id = ${projectId}::uuid`;
563	
564	    this.realtime.toProject(projectId, RealtimeEvent.TASKS_REORDERED, { status, ordered_task_ids: ids }, { actor: userActor(user), originClientId: clientId });
565	    return { status, ordered_task_ids: ids };
566	  }
567	
568	  // ================= Agent run control =================
569	
570	  async retryAgentRun(user: AuthUser, taskId: string) {
571	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
572	    if (task.assignee_type !== 'agent' || !task.assignee_agent_id) {
573	      throw Errors.business(ErrorCode.INVALID_ASSIGNEE, 'Task tidak di-assign ke agent');
574	    }
575	    const agent = await this.prisma.agents.findFirst({ where: { id: task.assignee_agent_id, deleted_at: null } });
576	    if (!agent?.is_active) throw Errors.business(ErrorCode.AGENT_INACTIVE, 'Agent tidak aktif');
577	    const active = await this.prisma.agent_runs.findFirst({
578	      where: { task_id: taskId, trigger: 'assignment', status: { in: ['queued', 'dispatched', 'running'] } },
579	    });
580	    if (active) throw Errors.conflict(ErrorCode.ALREADY_EXISTS, 'Agent masih mengerjakan task ini');
581	
582	    const effects = new AfterCommit();
583	    const run = await this.prisma.tx((tx) =>
584	      this.runs.createRun(
585	        tx,
586	        { workspaceId: workspace.id, projectId: task.project_id, taskId, agentId: agent.id, trigger: 'assignment', dispatchedBy: user.id },
587	        effects,
588	      ),
589	    );
590	    await effects.run();
591	    return { run_id: run.id, status: run.status };
592	  }
593	
594	  async cancelAgentRun(user: AuthUser, taskId: string) {
595	    const { task } = await this.access.assertTask(user.id, taskId, 'member');
596	    const effects = new AfterCommit();
597	    const count = await this.prisma.tx((tx) => this.runs.cancelActive(tx, { task_id: taskId }, 'user_cancelled', userActor(user), effects));
598	    await effects.run();
599	    if (count === 0) throw Errors.conflict(ErrorCode.RUN_NOT_ACTIVE, 'Tidak ada agent yang sedang mengerjakan task ini');
600	    return { cancelled: count, task_id: task.id };
601	  }
602	}
