1	import { Injectable } from '@nestjs/common';
2	import { randomUUID } from 'node:crypto';
3	import { ErrorCode } from '../../common/constants/error-codes';
4	import { TASK_STATUSES } from '../../common/constants/domain';
5	import { Errors } from '../../common/exceptions/app.exception';
6	import { Actor, AuthUser, userActor } from '../../common/types/request.types';
7	import { PrismaService, Tx } from '../../database/prisma.service';
8	import { Prisma, task_priority, task_status, tasks } from '../../generated/prisma/client';
9	import { AfterCommit } from '../../utils/helpers/after-commit';
10	import { addDays, diffDays, fromDateString, toDateString } from '../../utils/helpers/date.util';
11	import { decodeCursor, toPage } from '../../utils/helpers/pagination.util';
12	import { ActivityService } from '../activity/activity.service';
13	import { AgentRunsService } from '../agent-runs/agent-runs.service';
14	import { AccessService } from '../core/access.service';
15	import { RealtimeEvent } from '../realtime/realtime.events';
16	import { RealtimeService } from '../realtime/realtime.service';
17	import { ResolvedAssignee, TaskAssignmentService } from './task-assignment.service';
18	import { subtreeHeight, TaskHierarchy } from './task-hierarchy.repository';
19	import { TaskReaderService } from './task-reader.service';
20	import { taskInclude } from './task.mapper';
21	import { assertMoveDepth, childDepth, normalizeSchedule, uniqueTags } from './task.rules';
22	import { CreateTaskInput, DuplicateTaskInput, ListTasksQuery, UpdateTaskInput } from './tasks.schemas';
23	
24	export interface CreateTaskParams {
25	  workspaceId: string;
26	  projectId: string;
27	  parent: Pick<tasks, 'id' | 'depth' | 'project_id'> | null;
28	  title: string;
29	  status?: task_status;
30	  priority?: task_priority;
31	  assignee: ResolvedAssignee | null;
32	  startDate?: string | null;
33	  endDate?: string | null;
34	  isMilestone?: boolean;
35	  tags?: string[];
36	  afterTaskId?: string;
37	  actor: Actor;
38	  /** false untuk subtask agent "assign_to_self" agar tidak memicu dispatch baru */
39	  triggerAssignmentEffects?: boolean;
40	}
41	
42	@Injectable()
43	export class TasksService {
44	  constructor(
45	    private readonly prisma: PrismaService,
46	    private readonly access: AccessService,
47	    private readonly activity: ActivityService,
48	    private readonly realtime: RealtimeService,
49	    private readonly reader: TaskReaderService,
50	    private readonly assignment: TaskAssignmentService,
51	    private readonly runs: AgentRunsService,
52	  ) {}
53	
54	  // ================= Create =================
55	
56	  async create(user: AuthUser, projectId: string, parentTaskId: string | null, input: CreateTaskInput, clientId: string | null) {
57	    let workspaceId: string;
58	    let parent: tasks | null = null;
59	    if (parentTaskId) {
60	      const acc = await this.access.assertTask(user.id, parentTaskId, 'member');
61	      workspaceId = acc.workspace.id;
62	      parent = acc.task;
63	      projectId = acc.task.project_id;
64	    } else {
65	      workspaceId = (await this.access.assertProject(user.id, projectId, 'member')).workspace.id;
66	    }
67	    const assignee = (await this.assignment.resolve(workspaceId, input.assignee)) ?? null;
68	    const actor = userActor(user);
69	    const effects = new AfterCommit();
70	
71	    const task = await this.prisma.tx((tx) =>
72	      this.createInTx(
73	        tx,
74	        {
75	          workspaceId,
76	          projectId,
77	          parent,
78	          title: input.title,
79	          status: input.status,
80	          priority: input.priority,
81	          assignee,
82	          startDate: input.start_date,
83	          endDate: input.end_date,
84	          isMilestone: input.is_milestone,
85	          tags: input.tags,
86	          afterTaskId: input.after_task_id,
87	          actor,
88	        },
89	        effects,
90	      ),
91	    );
92	    const dto = await this.reader.getDto(task.id);
93	    effects.add(() => this.realtime.toProject(projectId, RealtimeEvent.TASK_CREATED, { task: dto }, { actor, originClientId: clientId }));
94	    await effects.run();
95	    return dto;
96	  }
97	
98	  /** Inti pembuatan task (dipakai API & webhook agent.subtask.created). */
99	  async createInTx(tx: Tx, p: CreateTaskParams, effects: AfterCommit): Promise<tasks> {
100	    if (p.parent && p.parent.project_id !== p.projectId) {
101	      throw Errors.business(ErrorCode.CROSS_PROJECT_PARENT, 'Parent task harus berada di project yang sama');
102	    }
103	    const depth = childDepth(p.parent?.depth ?? null);
104	    const schedule = normalizeSchedule({ start_date: p.startDate ?? null, end_date: p.endDate ?? null, is_milestone: p.isMilestone ?? false });
105	    const status = p.status ?? 'todo';
106	    const orderIndex = await this.nextOrderIndex(tx, p.projectId, status, p.afterTaskId);
107	
108	    const task = await tx.tasks.create({
109	      data: {
110	        project_id: p.projectId,
111	        parent_task_id: p.parent?.id ?? null,
112	        depth,
113	        title: p.title,
114	        status,
115	        priority: p.priority ?? 'none',
116	        ...this.assignment.columns(p.assignee),
117	        start_date: fromDateString(schedule.start_date),
118	        end_date: fromDateString(schedule.end_date),
119	        is_milestone: schedule.is_milestone,
120	        tags: uniqueTags(p.tags) ?? [],
121	        order_index: orderIndex,
122	        created_by_type: p.actor.type,
123	        created_by_id: p.actor.id,
124	        completed_at: status === 'done' ? new Date() : null,
125	      },
126	    });
127	    await this.activity.log(
128	      tx,
129	      {
130	        workspaceId: p.workspaceId,
131	        projectId: p.projectId,
132	        entityType: 'task',
133	        entityId: task.id,
134	        action: 'task.created',
135	        actor: p.actor,
136	        metadata: { title: task.title, parent_task_id: task.parent_task_id },
137	      },
138	      effects,
139	    );
140	    if (p.assignee && p.triggerAssignmentEffects !== false) {
141	      await this.assignment.afterChange(tx, { workspaceId: p.workspaceId, actor: p.actor }, null, task, p.assignee, effects);
142	    }
143	    return task;
144	  }
145	
146	  private async nextOrderIndex(tx: Tx, projectId: string, status: task_status, afterTaskId?: string): Promise<number> {
147	    if (afterTaskId) {
148	      const after = await tx.tasks.findFirst({ where: { id: afterTaskId, project_id: projectId, deleted_at: null } });
149	      if (!after) throw Errors.validation('after_task_id tidak ditemukan di project ini', { field: 'after_task_id' });
150	      if (after.status === status) {
151	        await tx.tasks.updateMany({
152	          where: { project_id: projectId, status, deleted_at: null, order_index: { gt: after.order_index } },
153	          data: { order_index: { increment: 1 } },
154	        });
155	        return after.order_index + 1;
156	      }
157	    }
158	    const max = await tx.tasks.aggregate({ where: { project_id: projectId, status, deleted_at: null }, _max: { order_index: true } });
159	    return (max._max.order_index ?? -1) + 1;
160	  }
161	
162	  // ================= Read =================
163	
164	  async list(user: AuthUser, projectId: string, q: ListTasksQuery) {
165	    await this.access.assertProject(user.id, projectId);
166	    const where: Prisma.tasksWhereInput = { project_id: projectId, deleted_at: null };
167	    if (q.status?.length) where.status = { in: q.status };
168	    if (q.priority?.length) where.priority = { in: q.priority };
169	    if (q.tag?.length) where.tags = { hasSome: q.tag };
170	    if (q.q) where.title = { contains: q.q, mode: 'insensitive' };
171	    if (q.assignee_type === 'none') where.assignee_type = null;
172	    else if (q.assignee_type) where.assignee_type = q.assignee_type;
173	    if (q.assignee_id) {
174	      const id = q.assignee_id === 'me' ? user.id : q.assignee_id;
175	      where.OR = [{ assignee_user_id: id }, { assignee_agent_id: id }];
176	    }
177	
178	    const desc = q.sort.startsWith('-');
179	    const field = q.sort.replace(/^-/, '') as 'order_index' | 'start_date' | 'end_date' | 'priority' | 'created_at';
180	    const dir: Prisma.SortOrder = desc ? 'desc' : 'asc';
181	    const orderBy: Prisma.tasksOrderByWithRelationInput[] =
182	      field === 'start_date' || field === 'end_date'
183	        ? [{ [field]: { sort: dir, nulls: 'last' } }, { order_index: 'asc' }]
184	        : [{ [field]: dir }, { created_at: 'asc' }];
185	
186	    if (q.view === 'board') {
187	      if (!q.include_subtasks) where.parent_task_id = null;
188	      const rows = await this.prisma.tasks.findMany({ where, include: taskInclude, orderBy: [{ order_index: 'asc' }, { created_at: 'asc' }] });
189	      const dtos = await this.reader.toDtos(rows);
190	      return { columns: TASK_STATUSES.map((status) => ({ status, tasks: dtos.filter((t) => t.status === status) })) };
191	    }
192	
193	    const offset = decodeCursor(q.cursor);
194	    const rows = await this.prisma.tasks.findMany({ where, include: taskInclude, orderBy, skip: offset, take: q.limit + 1 });
195	    const page = toPage(rows, offset, q.limit);
196	    return { data: await this.reader.toDtos(page.data), next_cursor: page.next_cursor };
197	  }
198	
199	  async detail(user: AuthUser, taskId: string) {
200	    await this.access.assertTask(user.id, taskId);
201	    const [task, breadcrumbs, children] = await Promise.all([
202	      this.reader.getDto(taskId),
203	      TaskHierarchy.ancestors(this.prisma, taskId),
204	      this.prisma.tasks.findMany({ where: { parent_task_id: taskId, deleted_at: null }, include: taskInclude, orderBy: [{ order_index: 'asc' }, { created_at: 'asc' }] }),
205	    ]);
206	    if (!task) throw Errors.notFound('Task tidak ditemukan');
207	    return { ...task, breadcrumbs: breadcrumbs.map((b) => ({ id: b.id, title: b.title })), subtasks: await this.reader.toDtos(children) };
208	  }
209	
210	  // ================= Update =================
211	
212	  async update(user: AuthUser, taskId: string, input: UpdateTaskInput, clientId: string | null) {
213	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
214	    const actor = userActor(user);
215	    const nextAssignee = await this.assignment.resolve(workspace.id, input.assignee);
216	    const assigneeChanged = nextAssignee !== undefined && !TaskAssignmentService.same(task, nextAssignee);
217	
218	    const schedule = normalizeSchedule({
219	      start_date: input.start_date !== undefined ? input.start_date : toDateString(task.start_date),
220	      end_date: input.end_date !== undefined ? input.end_date : toDateString(task.end_date),
221	      is_milestone: input.is_milestone ?? task.is_milestone,
222	    });
223	
224	    const data: Prisma.tasksUncheckedUpdateInput = {};
225	    const changed: string[] = [];
226	    const changes: Record<string, { from: unknown; to: unknown }> = {};
227	    const track = (field: string, from: unknown, to: unknown) => {
228	      if (JSON.stringify(from) !== JSON.stringify(to)) {
229	        changed.push(field);
230	        changes[field] = { from, to };
231	      }
232	    };
233	
234	    if (input.title !== undefined) track('title', task.title, input.title);
235	    if (input.priority !== undefined) track('priority', task.priority, input.priority);
236	    if (input.tags !== undefined) track('tags', task.tags, uniqueTags(input.tags));
237	    track('is_milestone', task.is_milestone, schedule.is_milestone);
238	    track('start_date', toDateString(task.start_date), schedule.start_date);
239	    track('end_date', toDateString(task.end_date), schedule.end_date);
240	    if (input.status !== undefined) track('status', task.status, input.status);
241	
242	    for (const f of changed) {
243	      if (f === 'start_date' || f === 'end_date') data[f] = fromDateString(changes[f].to as string | null);
244	      else data[f as 'title'] = changes[f].to as never;
245	    }
246	    if (changed.includes('status')) {
247	      const status = input.status as task_status;
248	      data.completed_at = status === 'done' ? new Date() : null;
249	      const max = await this.prisma.tasks.aggregate({ where: { project_id: task.project_id, status, deleted_at: null }, _max: { order_index: true } });
250	      data.order_index = (max._max.order_index ?? -1) + 1;
251	    }
252	    if (assigneeChanged) {
253	      Object.assign(data, this.assignment.columns(nextAssignee ?? null));
254	      changed.push('assignee');
255	    }
256	
257	    if (changed.length === 0) return this.reader.getDto(taskId);
258	
259	    const effects = new AfterCommit();
260	    await this.prisma.tx(async (tx) => {
261	      const updated = await tx.tasks.update({ where: { id: taskId }, data });
262	      const base = { workspaceId: workspace.id, projectId: task.project_id, entityType: 'task' as const, entityId: taskId, actor };
263	
264	      if (changes.status) await this.activity.log(tx, { ...base, action: 'task.status_changed', metadata: changes.status }, effects);
265	      if (changes.start_date || changes.end_date || changes.is_milestone) {
266	        await this.activity.log(
267	          tx,
268	          {
269	            ...base,
270	            action: 'task.rescheduled',
271	            metadata: {
272	              from: { start_date: toDateString(task.start_date), end_date: toDateString(task.end_date) },
273	              to: { start_date: schedule.start_date, end_date: schedule.end_date },
274	              cascade: 'none',
275	              shifted_count: 0,
276	            },
277	          },
278	          effects,
279	        );
280	      }
281	      const generic = Object.fromEntries(Object.entries(changes).filter(([k]) => ['title', 'priority', 'tags', 'is_milestone'].includes(k)));
282	      if (Object.keys(generic).length) await this.activity.log(tx, { ...base, action: 'task.updated', metadata: { changes: generic } }, effects);
283	      if (assigneeChanged) await this.assignment.afterChange(tx, { workspaceId: workspace.id, actor }, task, updated, nextAssignee ?? null, effects);
284	    });
285	
286	    const dto = await this.reader.getDto(taskId);
287	    effects.add(() =>
288	      this.realtime.toProjectAndTask(task.project_id, taskId, RealtimeEvent.TASK_UPDATED, { task: dto, changed_fields: changed }, { actor, originClientId: clientId }),
289	    );
290	    await effects.run();
291	    return dto;
292	  }
