333	  // ================= Duplicate =================
334	
335	  /**
336	   * Salin task beserta turunan terpilih ke parent yang sama (tepat setelah aslinya).
337	   * Salinan selalu berstatus To Do. Assignee AI Agent tidak disalin agar agent tidak otomatis bekerja.
338	   * Subtask yang parent-nya tidak dipilih ditempel ke leluhur terdekat yang ikut disalin.
339	   */
340	  async duplicate(user: AuthUser, taskId: string, input: DuplicateTaskInput, clientId: string | null) {
341	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
342	    const actor = userActor(user);
343	    const effects = new AfterCommit();
344	    const rootTitle = (input.title ?? `${task.title} (salinan)`).slice(0, 500);
345	
346	    const newIds = await this.prisma.tx(async (tx) => {
347	      // 1. Turunan yang ikut disalin, diurutkan preorder (parent selalu sebelum anaknya)
348	      const tree = input.subtasks === 'none' ? [] : await TaskHierarchy.descendants(tx, taskId);
349	      const descIds = tree.map((n) => n.id).filter((id) => id !== taskId);
350	      if (input.subtasks === 'selected') {
351	        const known = new Set(descIds);
352	        if (input.subtask_ids.some((id) => !known.has(id))) throw Errors.validation('Sebagian subtask_ids bukan turunan task ini', { field: 'subtask_ids' });
353	      }
354	      const all = descIds.length ? await tx.tasks.findMany({ where: { id: { in: descIds } } }) : [];
355	      const keep = new Set(input.subtasks === 'all' ? descIds : input.subtasks === 'selected' ? input.subtask_ids : []);
356	      const byId = new Map(all.map((t) => [t.id, t]));
357	      const parentOf = (t: tasks): string => {
358	        let p = t.parent_task_id;
359	        while (p && p !== taskId && !keep.has(p)) p = byId.get(p)?.parent_task_id ?? null;
360	        return p ?? taskId;
361	      };
362	      const children = new Map<string, tasks[]>();
363	      for (const t of all) {
364	        if (!keep.has(t.id)) continue;
365	        const p = parentOf(t);
366	        children.set(p, [...(children.get(p) ?? []), t]);
367	      }
368	      const byOrder = (a: tasks, b: tasks) => a.order_index - b.order_index || a.created_at.getTime() - b.created_at.getTime();
369	      const ordered: tasks[] = [];
370	      const walk = (pid: string) => {
371	        for (const c of (children.get(pid) ?? []).sort(byOrder)) {
372	          ordered.push(c);
373	          walk(c.id);
374	        }
375	      };
376	      walk(taskId);
377	
378	      // 2. Timeline: sama / digeser agar task utama mulai di start_date / dikosongkan
379	      let delta = 0;
380	      if (input.timeline === 'shift' && input.start_date) {
381	        const anchor = toDateString(task.start_date) ?? ordered.map((t) => toDateString(t.start_date)).filter((d): d is string => !!d).sort()[0];
382	        if (anchor) delta = diffDays(anchor, input.start_date);
383	      }
384	      const move = (d: Date | null) => (d && delta ? fromDateString(addDays(toDateString(d) as string, delta)) : d);
385	      const schedule = (t: tasks) =>
386	        input.timeline === 'none'
387	          ? { start_date: null, end_date: null, is_milestone: false }
388	          : { start_date: move(t.start_date), end_date: move(t.end_date), is_milestone: t.is_milestone };
389	
390	      // 3. Assignee: hanya user yang masih anggota aktif non-viewer
391	      const eligible = new Set<string>();
392	      if (input.copy_assignee) {
393	        const userIds = [...new Set([task, ...ordered].map((t) => t.assignee_user_id).filter((id): id is string => !!id))];
394	        if (userIds.length) {
395	          const members = await tx.workspace_members.findMany({
396	            where: { workspace_id: workspace.id, user_id: { in: userIds }, role: { not: 'viewer' }, user: { is_active: true } },
397	            select: { user_id: true },
398	          });
399	          for (const m of members) eligible.add(m.user_id);
400	        }
401	      }
402	      const assignee = (t: tasks) =>
403	        t.assignee_type === 'user' && t.assignee_user_id && eligible.has(t.assignee_user_id)
404	          ? { assignee_type: 'user' as const, assignee_user_id: t.assignee_user_id, assignee_agent_id: null }
405	          : { assignee_type: null, assignee_user_id: null, assignee_agent_id: null };
406	      const fields = (t: tasks) => ({
407	        project_id: task.project_id,
408	        status: 'todo' as const,
409	        priority: t.priority,
410	        tags: t.tags,
411	        created_by_type: actor.type,
412	        created_by_id: actor.id,
413	        ...schedule(t),
414	        ...assignee(t),
415	      });
416	
417	      // 4. Simpan: task utama tepat setelah aslinya, turunan di akhir kolom To Do
418	      const idMap = new Map<string, string>([[taskId, randomUUID()]]);
419	      const depthOf = new Map<string, number>([[taskId, task.depth]]);
420	      const rootId = idMap.get(taskId) as string;
421	      const rootOrder = await this.nextOrderIndex(tx, task.project_id, 'todo', taskId);
422	      await tx.tasks.create({
423	        data: { ...fields(task), id: rootId, parent_task_id: task.parent_task_id, depth: task.depth, title: rootTitle, order_index: rootOrder },
424	      });
425	      if (ordered.length) {
426	        const max = await tx.tasks.aggregate({ where: { project_id: task.project_id, status: 'todo', deleted_at: null }, _max: { order_index: true } });
427	        let next = (max._max.order_index ?? -1) + 1;
428	        const rows: Prisma.tasksCreateManyInput[] = ordered.map((t) => {
429	          const parent = parentOf(t);
430	          const depth = (depthOf.get(parent) as number) + 1;
431	          const id = randomUUID();
432	          idMap.set(t.id, id);
433	          depthOf.set(t.id, depth);
434	          return { ...fields(t), id, parent_task_id: idMap.get(parent) as string, depth, title: t.title, order_index: next++ };
435	        });
436	        await tx.tasks.createMany({ data: rows });
437	      }
438	
439	      // 5. Isi dokumen task (block editor), parent blok selalu disimpan lebih dulu
440	      if (input.copy_content) {
441	        const blocks = await tx.document_blocks.findMany({ where: { task_id: { in: [...idMap.keys()] }, deleted_at: null } });
442	        const blockIds = new Map(blocks.map((b) => [b.id, randomUUID()]));
443	        const sorted: typeof blocks = [];
444	        const placed = new Set<string>();
445	        let pending = blocks;
446	        while (pending.length) {
447	          const ready = pending.filter((b) => !b.parent_block_id || !blockIds.has(b.parent_block_id) || placed.has(b.parent_block_id));
448	          if (!ready.length) break;
449	          for (const b of ready) {
450	            sorted.push(b);
451	            placed.add(b.id);
452	          }
453	          pending = pending.filter((b) => !placed.has(b.id));
454	        }
455	        if (sorted.length) {
456	          await tx.document_blocks.createMany({
457	            data: sorted.map((b) => ({
458	              id: blockIds.get(b.id) as string,
459	              project_id: task.project_id,
460	              task_id: idMap.get(b.task_id as string) as string,
461	              parent_block_id: b.parent_block_id ? (blockIds.get(b.parent_block_id) ?? null) : null,
462	              block_type: b.block_type,
463	              content_json: b.content_json as Prisma.InputJsonValue,
464	              plain_text: b.plain_text,
465	              order_index: b.order_index,
466	              last_edited_by_type: actor.type,
467	              last_edited_by_id: actor.id,
468	            })),
469	          });
470	        }
471	      }
472	
473	      await this.activity.log(
474	        tx,
475	        {
476	          workspaceId: workspace.id,
477	          projectId: task.project_id,
478	          entityType: 'task',
479	          entityId: rootId,
480	          action: 'task.duplicated',
481	          actor,
482	          metadata: { title: rootTitle, source_task_id: taskId, source_title: task.title, subtask_count: ordered.length, parent_task_id: task.parent_task_id },
483	        },
484	        effects,
485	      );
486	      return [...idMap.values()];
487	    });
488	
489	    const dtos = await this.reader.getDtos(newIds);
490	    effects.add(() => {
491	      for (const dto of dtos) this.realtime.toProject(task.project_id, RealtimeEvent.TASK_CREATED, { task: dto }, { actor, originClientId: clientId });
492	    });
493	    await effects.run();
494	    return { task: dtos.find((d) => d.id === newIds[0]) ?? null, created_count: newIds.length };
495	  }
