497	  // ================= Move & reorder =================
498	
499	  async move(user: AuthUser, taskId: string, parentTaskId: string | null, clientId: string | null) {
500	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
501	    const actor = userActor(user);
502	    if (parentTaskId === task.parent_task_id) return this.reader.getDto(taskId);
503	
504	    const effects = new AfterCommit();
505	    const movedIds = await this.prisma.tx(async (tx) => {
506	      const subtree = await TaskHierarchy.descendants(tx, taskId);
507	      let newDepth = 1;
508	      if (parentTaskId) {
509	        if (subtree.some((n) => n.id === parentTaskId)) {
510	          throw Errors.business(ErrorCode.CIRCULAR_HIERARCHY, 'Task tidak dapat dipindahkan ke dalam turunannya sendiri');
511	        }
512	        const parent = await tx.tasks.findFirst({ where: { id: parentTaskId, deleted_at: null } });
513	        if (!parent) throw Errors.validation('parent_task_id tidak ditemukan', { field: 'parent_task_id' });
514	        if (parent.project_id !== task.project_id) {
515	          throw Errors.business(ErrorCode.CROSS_PROJECT_PARENT, 'Parent task harus berada di project yang sama');
516	        }
517	        newDepth = parent.depth + 1;
518	      }
519	      assertMoveDepth(newDepth, subtreeHeight(subtree, task.depth));
520	      const delta = newDepth - task.depth;
521	
522	      await tx.tasks.update({ where: { id: taskId }, data: { parent_task_id: parentTaskId } });
523	      if (delta !== 0) {
524	        await tx.tasks.updateMany({ where: { id: { in: subtree.map((n) => n.id) } }, data: { depth: { increment: delta } } });
525	      }
526	      await this.activity.log(
527	        tx,
528	        {
529	          workspaceId: workspace.id,
530	          projectId: task.project_id,
531	          entityType: 'task',
532	          entityId: taskId,
533	          action: 'task.moved',
534	          actor,
535	          metadata: { from_parent_id: task.parent_task_id, to_parent_id: parentTaskId },
536	        },
537	        effects,
538	      );
539	      return subtree.map((n) => n.id);
540	    });
541	    const dtos = await this.reader.getDtos(movedIds);
542	    effects.add(() => {
543	      for (const dto of dtos) {
544	        this.realtime.toProjectAndTask(task.project_id, dto.id, RealtimeEvent.TASK_UPDATED, { task: dto, changed_fields: ['parent_task_id', 'depth'] }, { actor, originClientId: clientId });
545	      }
546	    });
547	    await effects.run();
548	    return dtos.find((d) => d.id === taskId) ?? null;
549	  }
550	
551	  async reorder(user: AuthUser, projectId: string, status: task_status, orderedIds: string[], clientId: string | null) {
552	    await this.access.assertProject(user.id, projectId, 'member');
553	    const ids = [...new Set(orderedIds)];
554	    const found = await this.prisma.tasks.findMany({ where: { id: { in: ids }, project_id: projectId, deleted_at: null }, select: { id: true, status: true } });
555	    if (found.length !== ids.length) throw Errors.validation('Sebagian task tidak ditemukan di project ini', { field: 'ordered_task_ids' });
556	    if (found.some((t) => t.status !== status)) throw Errors.validation('Semua task harus berstatus sama dengan kolom', { field: 'status' });
557	
558	    const values = Prisma.join(ids.map((id, i) => Prisma.sql`(${id}::uuid, ${i}::int)`));
559	    await this.prisma.$executeRaw`
560	      UPDATE tasks AS t SET order_index = v.idx, updated_at = now()
561	      FROM (VALUES ${values}) AS v(id, idx)
562	      WHERE t.id = v.id AND t.project_id = ${projectId}::uuid`;
563	
564	    this.realtime.toProject(projectId, RealtimeEvent.TASKS_REORDERED, { status, ordered_task_ids: ids }, { actor: userActor(user), originClientId: clientId });
565	    return { status, ordered_task_ids: ids };
566	  }
