568	  // ================= Agent run control =================
569	
570	  async retryAgentRun(user: AuthUser, taskId: string) {
571	    const { task, workspace } = await this.access.assertTask(user.id, taskId, 'member');
572	    if (task.assignee_type !== 'agent' || !task.assignee_agent_id) {
573	      throw Errors.business(ErrorCode.INVALID_ASSIGNEE, 'Task tidak di-assign ke agent');
574	    }
575	    const agent = await this.prisma.agents.findFirst({ where: { id: task.assignee_agent_id, deleted_at: null } });
576	    if (!agent?.is_active) throw Errors.business(ErrorCode.AGENT_INACTIVE, 'Agent tidak aktif');
577	    const active = await this.prisma.agent_runs.findFirst({
578	      where: { task_id: taskId, trigger: 'assignment', status: { in: ['queued', 'dispatched', 'running'] } },
579	    });
580	    if (active) throw Errors.conflict(ErrorCode.ALREADY_EXISTS, 'Agent masih mengerjakan task ini');
581	
582	    const effects = new AfterCommit();
583	    const run = await this.prisma.tx((tx) =>
584	      this.runs.createRun(
585	        tx,
586	        { workspaceId: workspace.id, projectId: task.project_id, taskId, agentId: agent.id, trigger: 'assignment', dispatchedBy: user.id },
587	        effects,
588	      ),
589	    );
590	    await effects.run();
591	    return { run_id: run.id, status: run.status };
592	  }
593	
594	  async cancelAgentRun(user: AuthUser, taskId: string) {
595	    const { task } = await this.access.assertTask(user.id, taskId, 'member');
596	    const effects = new AfterCommit();
597	    const count = await this.prisma.tx((tx) => this.runs.cancelActive(tx, { task_id: taskId }, 'user_cancelled', userActor(user), effects));
598	    await effects.run();
599	    if (count === 0) throw Errors.conflict(ErrorCode.RUN_NOT_ACTIVE, 'Tidak ada agent yang sedang mengerjakan task ini');
600	    return { cancelled: count, task_id: task.id };
601	  }
602	}
