51	    const roots = await this.prisma.comments.findMany({
52	      where: { entity_type: entityType, entity_id: entityId, parent_comment_id: null, deleted_at: null },
53	      include: { ...commentInclude, replies: { where: { deleted_at: null }, include: commentInclude, orderBy: { created_at: 'asc' }, take: 50 } },
54	      orderBy: { created_at: 'asc' },
