179	      });
180	      await this.notifications.notify(
181	        tx,
182	        {
183	          recipients: users.filter((u) => !before.has(u.id)).map((u) => u.id),
184	          workspaceId: ctx.workspaceId,
185	          type: 'comment_mention',
186	          title: `${user.display_name} menyebut Anda di ${ctx.title}`,
