203	  async remove(user: AuthUser, commentId: string, clientId: string | null): Promise<void> {
204	    const existing = await this.findComment(commentId);
205	    const ctx = await this.resolveEntity(user, existing.entity_type as 'project' | 'task' | 'block', existing.entity_id, 'member');
206	    const isAuthor = existing.author_type === 'user' && existing.author_user_id === user.id;
207	    if (!isAuthor && !hasRole(ctx.role, 'admin')) throw Errors.forbidden('Hanya penulis atau Admin yang dapat menghapus komentar');
208	    const now = new Date();
209	    await this.prisma.comments.updateMany({ where: { OR: [{ id: commentId }, { parent_comment_id: commentId }], deleted_at: null }, data: { deleted_at: now } });
210	    this.realtime.toProjectAndTask(ctx.projectId, ctx.taskId, RealtimeEvent.COMMENT_DELETED, { comment_id: commentId }, { actor: userActor(user), originClientId: clientId });
