215	  /** Resolusi entity komentar + cek akses (dipakai juga oleh webhook agent dengan actor agent). */
216	  async resolveEntity(user: AuthUser, type: 'project' | 'task' | 'block', id: string, minRole: workspace_role): Promise<EntityContext> {
217	    if (type === 'project') {
218	      const a = await this.access.assertProject(user.id, id, minRole);
219	      return { workspaceId: a.workspace.id, projectId: a.project.id, taskId: null, title: a.project.title, role: a.role };
220	    }
221	    if (type === 'task') {
222	      const a = await this.access.assertTask(user.id, id, minRole);
223	      return { workspaceId: a.workspace.id, projectId: a.project.id, taskId: a.task.id, title: a.task.title, role: a.role };
224	    }
225	    const a = await this.access.assertBlock(user.id, id, minRole);
226	    const title = a.block.task_id
227	      ? ((await this.prisma.tasks.findUnique({ where: { id: a.block.task_id }, select: { title: true } }))?.title ?? a.project.title)
228	      : a.project.title;
229	    return { workspaceId: a.workspace.id, projectId: a.project.id, taskId: a.block.task_id, title, role: a.role };
230	  }
