232	  /** Mention valid = member workspace (user) atau agent workspace (belum dihapus). */
233	  async validateMentions(workspaceId: string, mentions: MentionRef[]) {
234	    const userIds = [...new Set(mentions.filter((m) => m.type === 'user').map((m) => m.id))];
235	    const agentIds = [...new Set(mentions.filter((m) => m.type === 'agent').map((m) => m.id))];
236	    const [members, agentsList] = await Promise.all([
237	      userIds.length
238	        ? this.prisma.workspace_members.findMany({ where: { workspace_id: workspaceId, user_id: { in: userIds } }, select: { user_id: true } })
239	        : [],
240	      agentIds.length
241	        ? this.prisma.agents.findMany({ where: { workspace_id: workspaceId, id: { in: agentIds }, deleted_at: null }, select: { id: true, handle: true, is_active: true } })
242	        : [],
243	    ]);
244	    const users = members.map((m) => ({ id: m.user_id }));
245	    const valid: MentionRef[] = [...users.map((u) => ({ type: 'user' as const, id: u.id })), ...agentsList.map((a) => ({ type: 'agent' as const, id: a.id }))];
246	    return { valid, users, agents: agentsList };
247	  }
248	
249	  /** Maks 10 run mention per task (atau per project untuk komentar level project) per jam. */
250	  private async withinMentionLimit(tx: Tx, ctx: EntityContext): Promise<boolean> {
251	    const count = await tx.agent_runs.count({
252	      where: { trigger: 'mention', project_id: ctx.projectId, task_id: ctx.taskId, created_at: { gt: new Date(Date.now() - 3_600_000) } },
253	    });
254	    return count < MENTION_RUNS_PER_HOUR;
255	  }
256	
257	  private async systemComment(tx: Tx, ctx: EntityContext, parentId: string, content: string, effects: AfterCommit): Promise<void> {
258	    const c = await tx.comments.create({
259	      data: {
260	        project_id: ctx.projectId,
261	        entity_type: ctx.taskId ? 'task' : 'project',
262	        entity_id: ctx.taskId ?? ctx.projectId,
263	        parent_comment_id: parentId,
264	        author_type: 'system',
265	        content,
266	      },
267	      include: commentInclude,
268	    });
269	    const dto = this.toDto(c, new Map());
270	    effects.add(() => this.realtime.toProjectAndTask(ctx.projectId, ctx.taskId, RealtimeEvent.COMMENT_CREATED, { comment: dto }, { actor: { type: 'system', id: null } }));
271	  }
272	
273	  private async findComment(id: string) {
274	    const c = await this.prisma.comments.findFirst({ where: { id, deleted_at: null } });
275	    if (!c) throw Errors.notFound('Komentar tidak ditemukan');
276	    return c;
277	  }
278	
279	  private async mentionNames(comments: CommentRow[]): Promise<Map<string, string>> {
280	    const refs = comments.flatMap((c) => (c.mentions ?? []) as MentionRef[]);
281	    const resolve = await this.actors.resolve(refs);
282	    return new Map(refs.map((r) => [`${r.type}:${r.id}`, resolve(r)?.name ?? '']));
283	  }
284	
285	  toDto(c: CommentRow, mentionNames: Map<string, string>) {
286	    const author: Actor & { avatar_url: string | null } =
287	      c.author_type === 'user' && c.author_user
288	        ? { type: 'user', id: c.author_user.id, name: c.author_user.display_name, avatar_url: c.author_user.avatar_url }
289	        : c.author_type === 'agent' && c.author_agent
290	          ? { type: 'agent', id: c.author_agent.id, name: c.author_agent.name, avatar_url: c.author_agent.avatar_url }
291	          : { type: 'system', id: null, name: 'Sistem', avatar_url: null };
292	    return {
293	      id: c.id,
294	      project_id: c.project_id,
295	      entity_type: c.entity_type,
296	      entity_id: c.entity_id,
297	      parent_comment_id: c.parent_comment_id,
298	      author,
299	      content: c.content,
300	      mentions: ((c.mentions ?? []) as MentionRef[]).map((m) => ({ ...m, name: mentionNames.get(`${m.type}:${m.id}`) ?? null })),
301	      edited_at: c.edited_at,
302	      created_at: c.created_at,
303	      reply_count: c._count.replies,
304	    };
305	  }
306	}
