1	import { Injectable } from '@nestjs/common';
2	import { randomUUID } from 'node:crypto';
3	import { AppConfigService } from '../../config/app-config.service';
4	import { ErrorCode } from '../../common/constants/error-codes';
5	import { Errors } from '../../common/exceptions/app.exception';
6	import { Actor, AuthUser, userActor } from '../../common/types/request.types';
7	import { PrismaService, Tx } from '../../database/prisma.service';
8	import { document_blocks, Prisma, workspace_role } from '../../generated/prisma/client';
9	import {
10	  BlockContent,
11	  extractMentions,
12	  extractPlainText,
13	  replaceInvalidMentions,
