15	} from '../../shared/schemas/block.schema';
16	import { AfterCommit } from '../../utils/helpers/after-commit';
17	import { ActivityService } from '../activity/activity.service';
18	import { AgentRunsService } from '../agent-runs/agent-runs.service';
19	import { AccessService } from '../core/access.service';
20	import { ActorService } from '../core/actor.service';
21	import { NotificationsService } from '../notifications/notifications.service';
22	import { RealtimeEvent } from '../realtime/realtime.events';
23	import { RealtimeService } from '../realtime/realtime.service';
24	import { BlockDto, buildBlockTree, toBlockDto } from './block.mapper';
25	import { BatchBlocksInput, CreateBlockInput, ReorderBlocksInput, UpdateBlockInput } from './blocks.schemas';
26	
27	export interface BlockScope {
28	  workspaceId: string;
29	  projectId: string;
30	  taskId: string | null;
31	  /** Judul task/project untuk teks notifikasi */
32	  title: string;
33	}
34	
35	/** Operasi internal. mode: insert (harus baru), update (harus ada), upsert (keduanya). */
36	export type BlockOperation =
37	  | {
38	      op: 'upsert';
39	      mode: 'insert' | 'update' | 'upsert';
40	      block: { id: string; parent_block_id?: string | null; block_type?: string; content_json: unknown; order_index?: number };
41	      after_block_id?: string | null;
42	      expected_version?: number;
43	    }
44	  | { op: 'delete'; id: string; expected_version?: number };
45	
46	export interface ApplyOptions {
47	  /** User wajib mengirim expected_version saat mengubah blok yang sudah ada; agent boleh last-write-wins. */
48	  requireVersionForUpdate: boolean;
49	}
50	
51	export interface ApplyResult {
52	  applied: { id: string; version: number }[];
53	  conflicts: { id: string; server_version: number | null; server_block: document_blocks | null }[];
54	  upserted: document_blocks[];
55	  deletedIds: string[];
56	  newUserMentions: string[];
57	}
58	
59	@Injectable()
60	export class BlocksService {
61	  constructor(
62	    private readonly prisma: PrismaService,
63	    private readonly access: AccessService,
64	    private readonly actors: ActorService,
65	    private readonly activity: ActivityService,
66	    private readonly notifications: NotificationsService,
67	    private readonly realtime: RealtimeService,
68	    private readonly runs: AgentRunsService,
69	    private readonly config: AppConfigService,
70	  ) {}
71	
72	  // ================= Read =================
73	
74	  async taskBlocks(user: AuthUser, taskId: string) {
75	    const { task } = await this.access.assertTask(user.id, taskId);
76	    return { blocks: await this.tree(task.project_id, task.id) };
77	  }
78	
79	  async briefBlocks(user: AuthUser, projectId: string) {
80	    await this.access.assertProject(user.id, projectId);
81	    return { blocks: await this.tree(projectId, null) };
82	  }
83	
84	  async tree(projectId: string, taskId: string | null): Promise<BlockDto[]> {
85	    const rows = await this.prisma.document_blocks.findMany({ where: { project_id: projectId, task_id: taskId, deleted_at: null } });
86	    return buildBlockTree(await this.toDtos(rows));
87	  }
88	
89	  async toDtos(rows: document_blocks[]): Promise<BlockDto[]> {
90	    const resolve = await this.actors.resolve(rows.map((r) => ({ type: r.last_edited_by_type, id: r.last_edited_by_id })));
91	    return rows.map((r) => toBlockDto(r, resolve({ type: r.last_edited_by_type, id: r.last_edited_by_id })));
92	  }
93	
94	  // ================= Write (API user) =================
95	
96	  async create(user: AuthUser, input: CreateBlockInput, clientId: string | null) {
97	    const scope = await this.resolveScope(user, input.project_id, input.task_id ?? null, 'member');
98	    const id = input.id ?? randomUUID();
99	    const result = await this.execute(
100	      user,
101	      scope,
102	      [
103	        {
104	          op: 'upsert',
105	          mode: 'insert',
106	          block: { id, parent_block_id: input.parent_block_id ?? null, block_type: input.block_type, content_json: input.content_json },
107	          after_block_id: input.after_block_id,
108	        },
109	      ],
110	      clientId,
111	    );
112	    if (result.conflicts.length) throw Errors.conflict(ErrorCode.ALREADY_EXISTS, 'ID blok sudah dipakai');
113	    return (await this.toDtos(result.upserted))[0];
114	  }
115	
116	  async update(user: AuthUser, blockId: string, input: UpdateBlockInput, clientId: string | null) {
117	    const { block, workspace, project } = await this.access.assertBlock(user.id, blockId, 'member');
118	    const scope = await this.scopeFrom(workspace.id, project.id, project.title, block.task_id);
119	    const result = await this.execute(
120	      user,
121	      scope,
122	      [
123	        {
124	          op: 'upsert',
125	          mode: 'update',
126	          block: { id: blockId, block_type: input.block_type, content_json: input.content_json },
127	          expected_version: input.expected_version,
128	        },
129	      ],
130	      clientId,
131	    );
132	    if (result.conflicts.length) {
133	      const server = result.conflicts[0].server_block;
134	      throw Errors.conflict(ErrorCode.VERSION_CONFLICT, 'Blok telah diubah oleh pihak lain', {
135	        server_block: server ? (await this.toDtos([server]))[0] : null,
136	      });
137	    }
138	    return (await this.toDtos(result.upserted))[0];
139	  }
140	
141	  async remove(user: AuthUser, blockId: string, clientId: string | null): Promise<void> {
142	    const { block, workspace, project } = await this.access.assertBlock(user.id, blockId, 'member');
143	    const scope = await this.scopeFrom(workspace.id, project.id, project.title, block.task_id);
144	    await this.execute(user, scope, [{ op: 'delete', id: blockId }], clientId);
145	  }
146	
147	  async batch(user: AuthUser, input: BatchBlocksInput, clientId: string | null) {
148	    const scope = await this.resolveScope(user, input.project_id, input.task_id ?? null, 'member');
149	    const ops: BlockOperation[] = input.operations.map((o) =>
150	      o.op === 'delete' ? o : { op: 'upsert', mode: 'upsert', block: o.block, expected_version: o.expected_version },
151	    );
152	    const result = await this.execute(user, scope, ops, clientId);
153	    const conflictDtos = await this.toDtos(result.conflicts.map((c) => c.server_block).filter((b): b is document_blocks => !!b));
154	    const byId = new Map(conflictDtos.map((d) => [d.id, d]));
155	    return {
156	      applied: result.applied,
157	      conflicts: result.conflicts.map((c) => ({ id: c.id, server_block: byId.get(c.id) ?? null })),
158	    };
159	  }
160	
161	  async reorder(user: AuthUser, input: ReorderBlocksInput, clientId: string | null) {
162	    const scope = await this.resolveScope(user, input.project_id, input.task_id ?? null, 'member');
163	    const ids = [...new Set(input.ordered_ids)];
164	    if (input.parent_block_id && ids.includes(input.parent_block_id)) throw Errors.validation('Blok tidak dapat menjadi parent dirinya sendiri');
165	    const found = await this.prisma.document_blocks.count({
166	      where: { id: { in: [...ids, ...(input.parent_block_id ? [input.parent_block_id] : [])] }, project_id: scope.projectId, task_id: scope.taskId, deleted_at: null },
167	    });
168	    if (found !== ids.length + (input.parent_block_id ? 1 : 0)) throw Errors.validation('Sebagian blok tidak ditemukan di dokumen ini');
169	
170	    await this.prisma.tx(async (tx) => {
171	      const values = Prisma.join(ids.map((id, i) => Prisma.sql`(${id}::uuid, ${i}::int)`));
172	      await tx.$executeRaw`
173	        UPDATE document_blocks AS b SET order_index = v.idx, parent_block_id = ${input.parent_block_id}::uuid, updated_at = now()
174	        FROM (VALUES ${values}) AS v(id, idx) WHERE b.id = v.id`;
175	      await this.normalizeOrder(tx, scope, input.parent_block_id);
176	    });
177	    this.realtime.toTaskOrProject(scope.projectId, scope.taskId, RealtimeEvent.BLOCKS_REORDERED, {
178	      task_id: scope.taskId,
179	      project_id: scope.projectId,
180	      parent_block_id: input.parent_block_id,
181	      ordered_ids: ids,
182	    }, { actor: userActor(user), originClientId: clientId });
183	    return { parent_block_id: input.parent_block_id, ordered_ids: ids };
184	  }
185	
186	  /** Jalankan AI Prompt Block (P1, feature flag FEATURE_AI_PROMPT_BLOCK). */
187	  async runPrompt(user: AuthUser, blockId: string) {
188	    if (!this.config.env.FEATURE_AI_PROMPT_BLOCK) throw Errors.notFound();
189	    const { block, workspace } = await this.access.assertBlock(user.id, blockId, 'member');
190	    if (block.block_type !== 'aiPrompt') throw Errors.validation('Blok bukan AI Prompt');
191	    const props = ((block.content_json ?? {}) as { props?: { prompt?: string; agent_id?: string | null } }).props ?? {};
192	    if (!props.prompt?.trim()) throw Errors.validation('Prompt masih kosong');
193	    if (!props.agent_id) throw Errors.validation('Pilih agent terlebih dahulu');
194	    const agent = await this.prisma.agents.findFirst({ where: { id: props.agent_id, workspace_id: workspace.id, deleted_at: null } });
195	    if (!agent) throw Errors.business(ErrorCode.INVALID_ASSIGNEE, 'Agent tidak ditemukan');
196	    if (!agent.is_active) throw Errors.business(ErrorCode.AGENT_INACTIVE, `Agent ${agent.name} tidak aktif`);
197	    const active = await this.prisma.agent_runs.findFirst({ where: { trigger_ref_id: blockId, status: { in: ['queued', 'dispatched', 'running'] } } });
198	    if (active) throw Errors.conflict(ErrorCode.ALREADY_EXISTS, 'Prompt ini sedang dijalankan');
199	
200	    const effects = new AfterCommit();
201	    const run = await this.prisma.tx(async (tx) => {
202	      const r = await this.runs.createRun(
203	        tx,
204	        { workspaceId: workspace.id, projectId: block.project_id, taskId: block.task_id, agentId: agent.id, trigger: 'prompt_block', triggerRefId: blockId, dispatchedBy: user.id },
205	        effects,
206	      );
207	      await this.runs.setPromptBlockStatus(tx, blockId, 'running', r.id, userActor(user), effects);
208	      return r;
209	    });
210	    await effects.run();
211	    return { run_id: run.id, status: run.status };
212	  }
213	
214	  // ================= Core =================
215	
216	  /** Menjalankan operasi untuk user + efek samping standar (real-time, activity, notifikasi mention). */
217	  private async execute(user: AuthUser, scope: BlockScope, ops: BlockOperation[], clientId: string | null): Promise<ApplyResult> {
218	    const actor = userActor(user);
219	    const effects = new AfterCommit();
220	    const result = await this.prisma.tx((tx) => this.applyOperations(tx, scope, ops, actor, { requireVersionForUpdate: true }, effects));
221	    effects.add(() => this.emitChanges(scope, result, actor, clientId));
222	    if (scope.taskId && (result.upserted.length || result.deletedIds.length)) {
223	      const taskId = scope.taskId;
224	      effects.add(async () => {
225	        if (await this.activity.acquireThrottle(`content:${user.id}:${taskId}`, 600)) {
226	          const fx = new AfterCommit();
227	          await this.activity.log(
228	            this.prisma,
229	            {
230	              workspaceId: scope.workspaceId,
231	              projectId: scope.projectId,
232	              entityType: 'task',
233	              entityId: taskId,
234	              action: 'task.content_edited',
235	              actor,
236	              metadata: { block_count: result.upserted.length + result.deletedIds.length },
237	            },
238	            fx,
239	          );
240	          await fx.run();
241	        }
242	      });
243	    }
244	    if (result.newUserMentions.length) {
245	      effects.add(async () => {
246	        const fx = new AfterCommit();
247	        await this.notifications.notify(
248	          this.prisma,
249	          {
250	            recipients: result.newUserMentions,
251	            workspaceId: scope.workspaceId,
252	            type: 'comment_mention',
253	            title: `${user.display_name} menyebut Anda di dokumen ${scope.title}`,
254	            projectId: scope.projectId,
255	            entityType: scope.taskId ? 'task' : 'project',
256	            entityId: scope.taskId ?? scope.projectId,
257	            actor,
258	          },
259	          fx,
260	        );
261	        await fx.run();
262	      });
263	    }
264	    await effects.run();
265	    return result;
266	  }
267	
268	  async emitChanges(scope: BlockScope, result: ApplyResult, actor: Actor, clientId: string | null): Promise<void> {
269	    const meta = { actor, originClientId: clientId };
270	    if (result.upserted.length) {
271	      this.realtime.toTaskOrProject(scope.projectId, scope.taskId, RealtimeEvent.BLOCK_UPSERTED, {
272	        task_id: scope.taskId,
273	        project_id: scope.projectId,
274	        blocks: await this.toDtos(result.upserted),
275	      }, meta);
276	    }
277	    if (result.deletedIds.length) {
278	      this.realtime.toTaskOrProject(scope.projectId, scope.taskId, RealtimeEvent.BLOCK_DELETED, {
279	        task_id: scope.taskId,
280	        project_id: scope.projectId,
281	        block_ids: result.deletedIds,
282	      }, meta);
283	    }
284	  }
285	
286	  /**
287	   * Inti operasi blok (dipakai API batch & webhook agent):
288	   * validasi schema → sanitasi mention → cek scope/parent → optimistic locking → normalisasi urutan.
289	   */
290	  async applyOperations(tx: Tx, scope: BlockScope, ops: BlockOperation[], actor: Actor, opts: ApplyOptions, _effects?: AfterCommit): Promise<ApplyResult> {
291	    // 1. Validasi schema per operasi
292	    const normalized = new Map<number, { blockType?: string; content?: BlockContent }>();
293	    const issues: { operation_index: number; path: string; message: string }[] = [];
294	    ops.forEach((op, i) => {
295	      if (op.op !== 'upsert') return;
296	      if (op.block.block_type === undefined && op.mode !== 'update') {
297	        issues.push({ operation_index: i, path: 'block_type', message: 'block_type wajib diisi' });
298	        return;
299	      }
300	      normalized.set(i, { blockType: op.block.block_type });
301	    });
302	
303	    const ids = [...new Set(ops.map((o) => (o.op === 'delete' ? o.id : o.block.id)))];
304	    const existingRows = ids.length ? await tx.document_blocks.findMany({ where: { id: { in: ids } } }) : [];
305	    const existing = new Map(existingRows.map((b) => [b.id, b]));
306	
307	    for (const row of existingRows) {
308	      if (row.project_id !== scope.projectId || row.task_id !== scope.taskId) {
309	        throw Errors.validation('Blok bukan milik dokumen ini', { block_id: row.id });
310	      }
311	    }
312	
313	    ops.forEach((op, i) => {
314	      if (op.op !== 'upsert' || !normalized.has(i)) return;
315	      const blockType = op.block.block_type ?? existing.get(op.block.id)?.block_type;
316	      if (!blockType) {
317	        issues.push({ operation_index: i, path: 'block.id', message: 'Blok tidak ditemukan' });
318	        return;
319	      }
320	      const res = validateBlockContent(blockType, op.block.content_json);
321	      if (!res.ok) res.issues.forEach((iss) => issues.push({ operation_index: i, ...iss }));
322	      else normalized.set(i, { blockType, content: res.content });
323	    });
324	    if (issues.length) throw Errors.validation('Konten blok tidak valid', { issues });
325	
326	    // 2. Sanitasi mention: hanya member/agent workspace yang valid
327	    const mentionRefs = [...normalized.values()].flatMap((n) => (n.content ? extractMentions(n.content) : []));
328	    const validMentions = await this.validMentionSet(tx, scope.workspaceId, mentionRefs);
329	    for (const [i, n] of normalized) {
330	      if (n.content) normalized.set(i, { ...n, content: replaceInvalidMentions(n.content, (m) => validMentions.has(`${m.mention_type}:${m.id}`)) });
331	    }
332	
333	    // 3. Validasi parent (harus ada di dokumen yang sama atau dibuat di batch ini)
334	    const batchIds = new Set(ops.filter((o) => o.op === 'upsert').map((o) => (o as { block: { id: string } }).block.id));
335	    const parentIds = [
336	      ...new Set(
337	        ops.flatMap((o) => (o.op === 'upsert' && o.block.parent_block_id ? [o.block.parent_block_id] : [])).filter((p) => !batchIds.has(p) || existing.has(p)),
338	      ),
339	    ];
340	    if (parentIds.length) {
341	      const parents = await tx.document_blocks.count({ where: { id: { in: parentIds }, project_id: scope.projectId, task_id: scope.taskId, deleted_at: null } });
342	      if (parents !== parentIds.length) throw Errors.validation('parent_block_id tidak ditemukan di dokumen ini');
343	    }
344	    for (const o of ops) {
345	      if (o.op === 'upsert' && o.block.parent_block_id === o.block.id) throw Errors.validation('Blok tidak dapat menjadi parent dirinya sendiri');
346	    }
347	
348	    // 4. Urutkan: parent yang dibuat di batch ini diproses lebih dulu
349	    const order = this.topologicalOrder(ops);
350	
351	    const result: ApplyResult = { applied: [], conflicts: [], upserted: [], deletedIds: [], newUserMentions: [] };
352	    const touchedParents = new Set<string | null>();
353	    const now = new Date();
354	
355	    for (const i of order) {
356	      const op = ops[i];
357	      if (op.op === 'delete') {
358	        const row = existing.get(op.id);
359	        if (!row || row.deleted_at) continue; // idempotent
360	        if (op.expected_version !== undefined && op.expected_version !== row.version) {
361	          result.conflicts.push({ id: row.id, server_version: row.version, server_block: row });
362	          continue;
363	        }
364	        const subtree = await tx.$queryRaw<{ id: string }[]>`
365	          WITH RECURSIVE sub AS (
366	            SELECT id FROM document_blocks WHERE id = ${row.id}::uuid
367	            UNION ALL
368	            SELECT b.id FROM document_blocks b JOIN sub ON b.parent_block_id = sub.id WHERE b.deleted_at IS NULL
369	          ) SELECT id::text AS id FROM sub`;
370	        const subtreeIds = subtree.map((s) => s.id);
371	        await tx.document_blocks.updateMany({ where: { id: { in: subtreeIds } }, data: { deleted_at: now } });
372	        result.deletedIds.push(...subtreeIds);
373	        touchedParents.add(row.parent_block_id);
374	        continue;
375	      }
376	
377	      const n = normalized.get(i)!;
378	      const content = n.content!;
379	      const plain = extractPlainText(n.blockType!, content);
380	      const row = existing.get(op.block.id);
381	      const editor = { last_edited_by_type: actor.type, last_edited_by_id: actor.id };
382	
383	      if (row) {
384	        if (op.mode === 'insert' || row.deleted_at) {
385	          result.conflicts.push({ id: row.id, server_version: row.deleted_at ? null : row.version, server_block: row.deleted_at ? null : row });
386	          continue;
387	        }
388	        if (op.expected_version === undefined && opts.requireVersionForUpdate) {
389	          throw Errors.validation('expected_version wajib untuk mengubah blok yang sudah ada', { operation_index: i, block_id: row.id });
390	        }
391	        if (op.expected_version !== undefined && op.expected_version !== row.version) {
392	          result.conflicts.push({ id: row.id, server_version: row.version, server_block: row });
393	          continue;
394	        }
395	        const parentId = op.block.parent_block_id === undefined ? row.parent_block_id : op.block.parent_block_id;
396	        const updated = await tx.document_blocks.update({
397	          where: { id: row.id },
398	          data: {
399	            block_type: n.blockType,
400	            content_json: content as unknown as Prisma.InputJsonValue,
401	            plain_text: plain,
402	            parent_block_id: parentId,
403	            order_index: op.block.order_index ?? row.order_index,
404	            version: { increment: 1 },
405	            ...editor,
406	          },
407	        });
408	        const before = new Set(extractMentions(row.content_json as unknown as BlockContent).map((m) => `${m.mention_type}:${m.id}`));
409	        result.newUserMentions.push(
410	          ...extractMentions(content)
411	            .filter((m) => m.mention_type === 'user' && !before.has(`user:${m.id}`))
412	            .map((m) => m.id),
413	        );
414	        touchedParents.add(row.parent_block_id);
415	        touchedParents.add(parentId);
416	        result.upserted.push(updated);
417	        result.applied.push({ id: updated.id, version: updated.version });
418	        continue;
419	      }
420	
421	      if (op.mode === 'update') throw Errors.validation('Blok yang akan diubah tidak ditemukan', { operation_index: i, block_id: op.block.id });
422	
423	      // Insert baru
424	      let parentId = op.block.parent_block_id ?? null;
425	      let orderIndex = op.block.order_index;
426	      if (orderIndex === undefined) {
427	        if (op.after_block_id) {
428	          const after = await tx.document_blocks.findFirst({
429	            where: { id: op.after_block_id, project_id: scope.projectId, task_id: scope.taskId, deleted_at: null },
430	          });
431	          if (!after) throw Errors.validation('after_block_id tidak ditemukan di dokumen ini', { operation_index: i });
432	          if (op.block.parent_block_id === undefined) parentId = after.parent_block_id;
433	          await tx.document_blocks.updateMany({
434	            where: { project_id: scope.projectId, task_id: scope.taskId, parent_block_id: parentId, deleted_at: null, order_index: { gt: after.order_index } },
435	            data: { order_index: { increment: 1 } },
436	          });
437	          orderIndex = after.order_index + 1;
438	        } else {
439	          const max = await tx.document_blocks.aggregate({
440	            where: { project_id: scope.projectId, task_id: scope.taskId, parent_block_id: parentId, deleted_at: null },
441	            _max: { order_index: true },
442	          });
443	          orderIndex = (max._max.order_index ?? -1) + 1;
444	        }
445	      }
446	      const created = await tx.document_blocks.create({
447	        data: {
448	          id: op.block.id,
449	          project_id: scope.projectId,
450	          task_id: scope.taskId,
451	          parent_block_id: parentId,
452	          block_type: n.blockType!,
453	          content_json: content as unknown as Prisma.InputJsonValue,
454	          plain_text: plain,
455	          order_index: orderIndex,
456	          ...editor,
457	        },
458	      });
459	      result.newUserMentions.push(...extractMentions(content).filter((m) => m.mention_type === 'user').map((m) => m.id));
460	      touchedParents.add(parentId);
461	      result.upserted.push(created);
462	      result.applied.push({ id: created.id, version: created.version });
463	    }
464	
465	    // 5. Normalisasi order_index (0..n) untuk parent yang tersentuh
466	    for (const parentId of touchedParents) await this.normalizeOrder(tx, scope, parentId);
467	    if (touchedParents.size && result.upserted.length) {
468	      const fresh = await tx.document_blocks.findMany({ where: { id: { in: result.upserted.map((b) => b.id) } } });
469	      const byId = new Map(fresh.map((b) => [b.id, b]));
470	      result.upserted = result.upserted.map((b) => byId.get(b.id) ?? b);
471	    }
472	    result.newUserMentions = [...new Set(result.newUserMentions)].filter((id) => validMentions.has(`user:${id}`) && id !== actor.id);
473	    return result;
474	  }
475	
476	  // ================= Helpers =================
477	
478	  async resolveScope(user: AuthUser, projectId: string, taskId: string | null, minRole: workspace_role): Promise<BlockScope> {
479	    if (taskId) {
480	      const { task, workspace } = await this.access.assertTask(user.id, taskId, minRole);
481	      if (task.project_id !== projectId) throw Errors.validation('task_id tidak berada di project_id tersebut');
482	      return { workspaceId: workspace.id, projectId, taskId, title: task.title };
483	    }
484	    const { workspace, project } = await this.access.assertProject(user.id, projectId, minRole);
485	    return { workspaceId: workspace.id, projectId, taskId: null, title: project.title };
486	  }
487	
488	  private async scopeFrom(workspaceId: string, projectId: string, projectTitle: string, taskId: string | null): Promise<BlockScope> {
489	    if (!taskId) return { workspaceId, projectId, taskId: null, title: projectTitle };
490	    const task = await this.prisma.tasks.findUnique({ where: { id: taskId }, select: { title: true } });
491	    return { workspaceId, projectId, taskId, title: task?.title ?? projectTitle };
492	  }
493	
494	  private async normalizeOrder(tx: Tx, scope: BlockScope, parentId: string | null): Promise<void> {
495	    await tx.$executeRaw`
496	      UPDATE document_blocks AS d SET order_index = s.rn
497	      FROM (
498	        SELECT id, (row_number() OVER (ORDER BY order_index, created_at, id) - 1)::int AS rn
499	        FROM document_blocks
500	        WHERE project_id = ${scope.projectId}::uuid
501	          AND task_id IS NOT DISTINCT FROM ${scope.taskId}::uuid
502	          AND parent_block_id IS NOT DISTINCT FROM ${parentId}::uuid
503	          AND deleted_at IS NULL
504	      ) AS s
505	      WHERE d.id = s.id AND d.order_index <> s.rn`;
506	  }
507	
508	  private async validMentionSet(tx: Tx, workspaceId: string, refs: { mention_type: 'user' | 'agent'; id: string }[]): Promise<Set<string>> {
509	    const userIds = [...new Set(refs.filter((r) => r.mention_type === 'user').map((r) => r.id))];
510	    const agentIds = [...new Set(refs.filter((r) => r.mention_type === 'agent').map((r) => r.id))];
511	    const set = new Set<string>();
512	    if (userIds.length) {
513	      const m = await tx.workspace_members.findMany({ where: { workspace_id: workspaceId, user_id: { in: userIds } }, select: { user_id: true } });
514	      m.forEach((x) => set.add(`user:${x.user_id}`));
515	    }
516	    if (agentIds.length) {
517	      const a = await tx.agents.findMany({ where: { workspace_id: workspaceId, id: { in: agentIds }, deleted_at: null }, select: { id: true } });
518	      a.forEach((x) => set.add(`agent:${x.id}`));
519	    }
520	    return set;
521	  }
522	
523	  /** Indeks operasi terurut sehingga blok parent yang dibuat di batch yang sama diproses lebih dulu. */
524	  private topologicalOrder(ops: BlockOperation[]): number[] {
525	    const idx = new Map<string, number>();
526	    ops.forEach((o, i) => o.op === 'upsert' && idx.set(o.block.id, i));
527	    const visited = new Set<number>();
528	    const out: number[] = [];
529	    const visit = (i: number, stack: Set<number>) => {
530	      if (visited.has(i) || stack.has(i)) return;
531	      stack.add(i);
532	      const o = ops[i];
533	      if (o.op === 'upsert' && o.block.parent_block_id) {
534	        const p = idx.get(o.block.parent_block_id);
535	        if (p !== undefined) visit(p, stack);
536	      }
537	      visited.add(i);
538	      out.push(i);
539	    };
540	    ops.forEach((_, i) => visit(i, new Set()));
541	    return out;
542	  }
543	}
