import { SEED_IDS } from '../../src/database/seeds/seed-ids';

const BASE = `${process.env.API_BASE_URL ?? 'http://localhost:3000'}/api/v1`;
const PASSWORD = process.env.SEED_DEMO_PASSWORD ?? 'Demo12345!';
const WS = SEED_IDS.wsDemo;

type Role = 'owner' | 'manager' | 'member' | 'viewer' | 'outsider';
const tokens = {} as Record<Role, string>;

interface ApiResult {
  status: number;
  body: any;
}

async function api(role: Role, method: string, path: string, body?: unknown): Promise<ApiResult> {
  const res = await fetch(`${BASE}${path}`, {
    method,
    headers: { Authorization: `Bearer ${tokens[role]}`, 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  return { status: res.status, body: text ? JSON.parse(text) : null };
}

const gt1 = {
  title: 'IT â€” Website Oktober 2026',
  period_type: 'monthly',
  period_start: '2026-10-01',
  period_end: '2026-10-31',
  visitors: 20000,
  leads: 800,
  sales_count: 200,
  revenue: '150000000',
  cost_maintenance: '10000000',
  cost_ads: '5000000',
};

const created: string[] = [];
const create = async (role: Role, patch: Record<string, unknown> = {}) => {
  const res = await api(role, 'POST', `/workspaces/${WS}/web-reports`, { ...gt1, ...patch });
  if (res.status === 201) created.push(res.body.id);
  return res;
};

beforeAll(async () => {
  for (const role of ['owner', 'manager', 'member', 'viewer', 'outsider'] as Role[]) {
    const res = await fetch(`${BASE}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ identifier: `${role}@demo.local`, password: PASSWORD }),
    });
    const body = (await res.json()) as { access_token: string };
    if (!res.ok) throw new Error(`Login ${role} gagal: ${JSON.stringify(body)}`);
    tokens[role] = body.access_token;
  }
});

afterAll(async () => {
  // Bersihkan data test (soft delete) agar tidak mengotori daftar demo
  for (const id of created) await api('owner', 'DELETE', `/web-reports/${id}`);
});

describe('Web Reports API', () => {
  it('create â†’ 201, hasil sesuai golden test GT-1', async () => {
    const res = await create('member');
    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({
      period_type: 'monthly',
      input: { visitors: 20000, revenue: '150000000.00', cost_ads: '5000000.00' },
      results: { lead_cr: 4, sales_cr: 1, lead_to_sales_cr: 25, aov: '750000.00', rpv: '7500.00', roas: 10, roi: 900 },
      formula_version: 1,
      version: 1,
      created_by: { type: 'user', name: 'Member Demo' },
    });
    expect(res.body.results.insights.map((i: { code: string }) => i.code)).toEqual(['COST_COVERED', 'RPV_ABOVE_CPV']);
  });
==== task.rules
import { MAX_TASK_DEPTH } from '../../common/constants/domain';
import { ErrorCode } from '../../common/constants/error-codes';
import { Errors } from '../../common/exceptions/app.exception';

export interface Schedule {
  start_date: string | null;
  end_date: string | null;
  is_milestone: boolean;
}

/**
 * Validasi & normalisasi jadwal (TASK_002 Â§Business Logic):
 * - end_date â‰¥ start_date
 * - milestone: wajib bertanggal dan start_date = end_date (tanggal yang kosong disamakan)
 */
export function normalizeSchedule(s: Schedule): Schedule {
  let { start_date, end_date } = s;
  if (s.is_milestone) {
    const date = start_date ?? end_date;
    if (!date) throw Errors.business(ErrorCode.INVALID_DATE_RANGE, 'Milestone wajib memiliki tanggal', { field: 'start_date' });
    start_date = date;
    end_date = date;
  }
  if (start_date && end_date && end_date < start_date) {
    throw Errors.business(ErrorCode.INVALID_DATE_RANGE, 'end_date tidak boleh lebih kecil dari start_date', { field: 'end_date' });
  }
  return { start_date, end_date, is_milestone: s.is_milestone };
}

/** Depth untuk anak dari parent tertentu (null = root). */
export function childDepth(parentDepth: number | null): number {
  const depth = parentDepth === null ? 1 : parentDepth + 1;
  if (depth > MAX_TASK_DEPTH) {
    throw Errors.business(ErrorCode.HIERARCHY_DEPTH_EXCEEDED, `Kedalaman task maksimal ${MAX_TASK_DEPTH} level`, { max_depth: MAX_TASK_DEPTH });
  }
  return depth;
}

/** Validasi pemindahan subtree: kedalaman akhir tidak boleh melebihi batas. */
export function assertMoveDepth(newRootDepth: number, height: number): void {
  if (newRootDepth + height > MAX_TASK_DEPTH) {
    throw Errors.business(ErrorCode.HIERARCHY_DEPTH_EXCEEDED, `Kedalaman task maksimal ${MAX_TASK_DEPTH} level`, { max_depth: MAX_TASK_DEPTH });
  }
}

export function uniqueTags(tags: string[] | undefined): string[] | undefined {
  return tags ? [...new Set(tags.map((t) => t.trim()).filter(Boolean))] : undefined;
}
